  str_mission_name_4220100 = "Bidat",
  str_mission_name_4220110 = "Arcana",
  str_mission_name_4220125 = "Eeriness",
  str_mission_desc_4001010 = "Untuk pertama kalinya dalam 17 tahun, kamu mencoba kemampuan psikismu. Apakah wanita muda di depanmu memberikan kesempatan untuk pergi?",
  str_mission_desc_4001020 = "Kamu belum pernah melihat kaummu, tetapi sekarang kamu punya teman.",
  str_mission_desc_4001030 = "Mungkin Colossus-nya sudah siap diaktifkan?",
  str_mission_desc_4001040 = "Aurorian takkan berhenti bertarung selama masih ada harapan.",
  str_mission_desc_4001041 = "Jumlah Eclipsite menjadi makin banyak. Sebaiknya cari cara lain jika keadaan makin sulit.",
  str_mission_desc_4001042 = "Test",
  str_mission_desc_4001043 = "Test",
  str_mission_desc_4001044 = "Test",
  str_mission_desc_4001045 = "Test",
  str_mission_desc_4001046 = "Test",
  str_mission_desc_4001047 = "Test",
  str_mission_desc_4001050 = "Dengan panduan Ms. Blanc, kamu lebih mengerti cara mencapai tempat tujuan.",
  str_mission_desc_4001051 = "Pertempuranmu sebelumnya lebih mudah. Aurorian dan kamu dipasangkan dengan cukup baik.",
  str_mission_desc_4001060 = "Pertempuran menjadi makin sulit seiring dengan pertumbuhanmu dan Aurorian.",
  str_mission_desc_4001070 = "Di saat momen kritis, tanah mulai berguncang dan ada sesuatu yang mendekat...",
  str_mission_desc_4001080 = "Soroz tidak bisa lepas landas sekarang. Kamu harus melawan banyak Eclipsite untuk lepas landas.",
  str_mission_desc_4001090 = "Eclipsite ada di setiap sudut Colossus! Lindungi sekuat tenaga!",
  str_mission_desc_4001100 = "Jumlah Eclipsite yang makin banyak menyerbu bagian vital di Colossus - Bridge.",
  str_mission_desc_4001101 = "Beberapa krisis yang tidak diketahui mengintai di sekitarmu.",
  str_mission_desc_4001110 = "Jika tak bisa menang dengan angka, kamu bisa coba skema.",
  str_mission_desc_4001120 = "Kamu harus pergi bersama semua rekanmu!",
  str_mission_desc_4001130 = "Bersama dengan deru mesinnya, Colossus meluncur. Namun, saingan yang lebih kuat dari Kraken keluar dari bayang-bayang.",
  str_mission_desc_4002015 = "Pengorbanan sekutu dan berita tak terduga... Semua ini tampaknya menghalangi jalan ke depan. Bagaimana keadaannya nanti?",
  str_mission_desc_4002010 = "Soroz jatuh di hutan belantara karena malafungsi.",
  str_mission_desc_4002035 = "Test",
  str_mission_desc_4002020 = "Kali ini kamu akan memimpin sekelompok orang yang kikuk...",
  str_mission_desc_4002030 = "Rediesel Wrench memang kuat. Namun, para Eclipsite ini menggiringmu ke jalan buntu.",
  str_mission_desc_4002031 = "Bertahanlah! Bala bantuan Illumina mungkin sedang dalam perjalanan. Kamu harus tetap kuat.",
  str_mission_desc_4002040 = "Dengan pertimbangan pertempuran dan cedera Vice, orang-orang Rediesel Wrench yang agresif menyudutkanmu.",
  str_mission_desc_4002050 = "Situasinya buruk. Eclipsite sepertinya maju ke arah Colossus...",
  str_mission_desc_4002060 = "Saat semua orang mengira bahwa Eclipsite tingkat tinggi yang bertanggung jawab, Eclipsite baru, Umbrahulk, muncul.",
  str_mission_desc_4002070 = "Eclipsite di bawah perintah Nozard telah mengancam warga di undercity. Kamu harus melarikan diri untuk menyimpan kekuatanmu!",
  str_mission_desc_4002080 = "Kamu mendadak diserang oleh Eclipsite. Untungnya, belum terlambat...",
  str_mission_desc_4002090 = "Undercity dikuasai oleh Eclipsite. Apakah semua telah berakhir?",
  str_mission_desc_4002100 = "Undercity 28 telah jatuh, dan Charon memiliki senjata terakhir untuk menyingkirkan musuh dan semua orang sekaligus.",
  str_mission_desc_4002101 = "Biarkan warga dan orang-orang yang terluka naik Colossus! Sekarang bukan waktunya bersantai!",
  str_mission_desc_4002110 = "Beban tanggung jawabmu makin besar. Teman, atasan, dan warga... Ke mana kamu harus pergi?",
  str_mission_desc_4002120 = [[
Ketika dikepung, teriakan Charon yang memekakkan telinga mendesakmu 
untuk pergi. Dia akan jatuh bersama Undercity 28...]],
  str_mission_desc_4003010 = "Dengan bantuan Vice dan Soroz, pencarian kaummu sepertinya berjalan dengan lancar.",
  str_mission_desc_4003020 = "Salah satu orang dari kaummu meminta bantuan. Sepertinya dia dalam bahaya?!",
  str_mission_desc_4003030 = "Sepertinya kamu kalah cepat. Jejak Eclipsite ada di mana-mana.",
  str_mission_desc_4003031 = "Sinyalnya jelek. \"Orang Itu\" sedang dikejar. Cepatlah.",
  str_mission_desc_4003040 = "Jalan menuju relik itu kasar dan menanjak, penuh dengan Eclipsite.",
  str_mission_desc_4003050 = "Gerombolan Eclipsite berdatangan. Siapa dalang di balik semua ini?",
  str_mission_desc_4003060 = [[
Kamu menemukannya! Namun, dia sedang diburu oleh 
musuh yang berubah menjadi pengkhianat --]],
  str_mission_desc_4003070 = "Tidak ada yang tahu betapa kuatnya musuhmu dulu. Walau begitu... Waktu tak bisa diputar kembali.",
  str_mission_desc_4003080 = "Schummer mendapatkan Think Tank Module. Sudah terlambat—Kamu tak boleh kabur!",
  str_mission_desc_4003090 = "Mendelson jadi makin lemah, tetapi kamu terus maju tanpa keraguan.",
  str_mission_desc_4003091 = "Kamu hampir sampai di tempat tujuan. Apakah kamu mencium aroma musuh?",
  str_mission_desc_4003100 = "Udaranya penuh ketidakpastian, diselimuti kabut tebal yang terhampar dalam kegelapan.",
  str_mission_desc_4003110 = "Energi gelap menguasai sekujur badan Mendelson. Tubuhnya seperti lilin yang ditiup angin!",
  str_mission_desc_4003120 = "Dikelilingi oleh kegelapan dan keresahan, kamu mendengar gemerisik percakapan para Eclipsite tingkat tinggi. Ujian terakhir sudah di depan mata.",
  str_mission_desc_4004010 = "Area timur Lower Lumopolis diserbu para Eclipsite. Waktu sangatlah berharga dan kamu harus menang.",
  str_mission_desc_4004020 = "Eclipsite terlihat di area barat! Yang melarikan diri membangkitkan iblis di mana-mana.",
  str_mission_desc_4004030 = "Jumlah Eclipsite lebih banyak dari perkiraanmu. Evakuasi dan suaka adalah segalanya \nbagi penduduk kota.",
  str_mission_desc_4004031 = "Guardian membabat habis sisa-sisa Eclipsite. Tak satu pun bisa \nlolos dari perburuan mereka.",
  str_mission_desc_4004040 = "Di sudut terpencil di area barat, Eclipsite yang dipanggil telah menunggu lama.",
  str_mission_desc_4004050 = "Eclipsite terus menyerang, mungkin ada sesuatu di balik ini semua...",
  str_mission_desc_4004060 = "Shelt memutuskan untuk melakukan apa pun demi mencapai tujuannya: Dia membangunkan saudarinya yang juga telah berubah menjadi Eclipsite...",
  str_mission_desc_4004070 = "Fokuslah mencari Eclipsite bersaudari dan kalahkan para hama yang gegabah itu.",
  str_mission_desc_4004080 = "Eclipsite bersaudari memang sudah merencanakannya, terus-menerus memanggil Eclipsite.",
  str_mission_desc_4004090 = "Ia makin dekat. Kamu hampir menangkap biang keladi yang merencanakan kerusuhan ini.",
  str_mission_desc_4004091 = "Singkirkan mereka semua. Jangan sampai ada yang tersisa.",
  str_mission_desc_4004100 = "Di mana pria mencurigakan itu? Siapa dia?",
  str_mission_desc_4004110 = "Darah Eclipsite bersaudari menodai kota ini. Mereka takkan bisa kembali.",
  str_mission_desc_4004120 = "Sudah waktunya untuk mengadili kakak beradik itu. Bagaimana musuh yang putus asa akan melawan...",
  str_mission_desc_4005010 = "Jumlah Colossus yang jatuh menunjukkan jumlah Caelestite yang dikorbankan, serta jumlah Eclipsite yang dibunuh...",
  str_mission_desc_4005020 = "Bagian dalam Colossus yang jatuh telah rusak parah sehingga jalan menuju Autonomous Growth Unit bergelombang dan bergolak.",
  str_mission_desc_4005030 = "Bahaya mengintai di antara relik dan Eclipsite tiba-tiba muncul dari bayang-bayang.",
  str_mission_desc_4005031 = "Mengikuti jejak Achilles merupakan cara untuk keluar dari bahaya.",
  str_mission_desc_4005040 = "Waspadalah. Kamu bisa terluka karena Eclipsite atau pun jebakan tersembunyi.",
  str_mission_desc_4005050 = "Umpan yang baik bisa lolos tanpa cedera.",
  str_mission_desc_4005060 = "Melodi yang indah dimainkan dengan lembut. Colossus mulai terbangun lagi dari tidurnya. Ini adalah hadiah terakhir, kaumku.",
  str_mission_desc_4005070 = "Orang yang tak terduga datang ke Colossus dan mengacaukan pikiranmu. Perlu berpikir panjang untuk mencari solusi.",
  str_mission_desc_4005080 = "Mengejar tentara tak ada habisnya, seperti lalat yang bertebaran.",
  str_mission_desc_4005090 = "5 menit lagi sebelum waktu habis. Apa keputusanmu?",
  str_mission_desc_4005091 = "Kemampuan menghindar dan strategi solid sangat diperlukan.",
  str_mission_desc_4005100 = "Jadilah orang yang proaktif, jangan diam seperti patung.",
  str_mission_desc_4005110 = "Selalu ada jalan jika kamu mau beradaptasi.",
  str_mission_desc_4005120 = "Hitung mundur akan segera berakhir. Akankah serangan mendadak membalik keadaan? Saatnya menghabisi Schummer!",
  str_mission_desc_4006010 = "Saat mengejar Flame Control Module di Whispering Corridor, kamu menemukan jejak sepatu bot tentara. Pasti itu milik si pengkhianat, Gertzurde.",
  str_mission_desc_4006020 = "Untuk mendahului Schummer, kamu mempercepat pencarianmu.",
  str_mission_desc_4006030 = "Satu musuh menyergap saat Carleen dan Vice berusaha menemukan Flame Control Module secepat mungkin...",
  str_mission_desc_4006031 = "Kegelapan, kedinginan, dan keheningan... Berjuang sendirian itu sangatlah sulit, kamu benar-benar tak menerima bantuan?",
  str_mission_desc_4006040 = "Bahkan dengan bantuan jarak jauh Sheol, belokan berliku-liku di Whispering Corridor membuatmu bingung.",
  str_mission_desc_4006050 = "Gertzurde tampak mengintai di depan. Apakah ini pertempuran terakhir?",
  str_mission_desc_4006060 = "\"Kau... membunuh Shelt!\" Pembalas dendam telah muncul di hadapanmu...",
  str_mission_desc_4006070 = "Flame Control Module sudah dekat. Apa yang direncakanan musuh...",
  str_mission_desc_4006080 = "Jumlah Eclipsite meningkat, dan pertempuran tiada akhir membuat semua orang lelah...",
  str_mission_desc_4006090 = "Tak pernah berhenti... Langkah kaki Gertzurde makin dekat dan kamu bisa mencium aroma balas dendam yang tak asing.",
  str_mission_desc_4006091 = "Apa pun yang terjadi, rekanmu akan datang untukmu, menghadapi bahaya apa pun...",
  str_mission_desc_4006100 = "Jebakan dan penyergap di sepanjang jalan tidak menghentikanmu. Ada hal yang harus ditanyakan Gertzurde kepada Schummer...",
  str_mission_desc_4006110 = "Akhirnya, kamu mencapai kedalaman Whispering Corridor, dan jika tak ada hal \"tak terduga\" yang terjadi, Flame Control Module seharusnya ada di sini...",
  str_mission_desc_4006120 = "Akankah Gertzurde mendapatkan apa yang diinginkannya? Akankah Schummer memenuhi manifestonya untuk bertarung sampai mati? Perjalananmu hampir selesai.",
  str_mission_desc_4007010 = "Kalian berpencar untuk memastikan bahwa bantuan dan operasi penyelamatan dilakukan bersamaan.",
  str_mission_desc_4007020 = "Banyak Eclipsite membanjiri Lower Lumopolis, tetapi sepertinya operasimu berjalan lancar, ya?",
  str_mission_desc_4007030 = "Kamu merasa putus asa karena tidak bisa merasakan Soroz, tetapi penduduk kota Lower Lumopolis harus dilindungi meskipun kamu tak punya kemampuan bertempur...",
  str_mission_desc_4007031 = "Pada saat ini, sesuatu sedang terjadi di Lumopolis...",
  str_mission_desc_4007040 = "Dikelilingi ancaman dan pertempuran liar di mana-mana, ini adalah ujian yang belum pernah kamu hadapi sebelumnya.",
  str_mission_desc_4007050 = "Operasi bantuan di Lower Lumopolis telah selesai, tetapi sekarang Uptown diserang?!",
  str_mission_desc_4007060 = "Saat kamu menuju ke Uptown, musuh aneh yang tak asing muncul, besar dan menyeramkan...",
  str_mission_desc_4007070 = "Ini adalah pertempuran untuk hal yang ingin dilindungi semua orang—",
  str_mission_desc_4007080 = "Ini adalah pertempuran yang menentukan hidup dan mati. Untuk memenangkannya, kamu harus mengalahkan waktu.",
  str_mission_desc_4007090 = "Kepanikan berangsur-angsur menumpuk tanpa henti. Kamu tak bisa membiarkan Eclipsite ini menghancurkan Soroz lagi!",
  str_mission_desc_4007100 = "Pesan dari Soroz. Mungkinkah...?!",
  str_mission_desc_4007110 = "Suhu di sekitar mulai turun dengan cepat dan kamu bisa mencium Schummer, di sana!",
  str_mission_desc_4007111 = "Apakah komponen 'kesadaran diri' Soroz benar-benar hilang? Apakah ikatanmu dengannya akan kandas?",
  str_mission_desc_4007120 = [[
Schummer menjadi orang yang benar-benar berbeda setelah memiliki semua modul.
Apakah ini pertempuran atau permainan... sepihak?]],
  str_mission_desc_4008020 = "Schummer menahanmu di Aviduz kemudian Vice datang untuk menyelamatkanmu. Kamu memutuskan untuk mencari Chief Vivian dan membawanya bersamamu...",
  str_mission_desc_4008030 = "Saat kamu bergerak, tubuhmu terasa aneh, tetapi tak ada waktu untuk memeriksanya. Kamu harus menemukan Vivian secepatnya.",
  str_mission_desc_4008040 = "Kamu melangkah dengan ringan dan menghadapi musuh dengan cepat di sepanjang jalan.",
  str_mission_desc_4008041 = "Menyesatkan, beralih pihak, dan menusuk dari belakang... Eclipsite akan tertangkap basah.",
  str_mission_desc_4008050 = "Bagian dalam Black Colossus sangatlah rumit, jadi kamu harus berhati-hati...",
  str_mission_desc_4008060 = "Schummer belum menemukanmu. Jalan terus, mungkin Chief Vivian ada di ruangan depan!",
  str_mission_desc_4008070 = "Saat Curie menerobos, kamu sampai di tempat Chief Vivian ditahan, dan musuh yang kuat menunggumu di sana...",
  str_mission_desc_4008090 = "Chief Vivian berhasil diselamatkan, jadi sekarang tugas kita adalah meninggalkan tempat menakutkan ini. Namun, apakah ini pilihan yang paling masuk akal?",
  str_mission_desc_4008100 = "Terdengar suara yang keras. Situasi telah berubah. Apakah Carleen berhasil, ataukah Schummer akhirnya menang!?",
  str_mission_desc_4008110 = "Strategimu berubah dari melarikan diri menjadi menyerang! Ini adalah kesempatan terakhirmu untuk melumpuhkan musuh dari dalam!",
  str_mission_desc_4008111 = "Cobaan dan kesengsaraan apa yang bisa kamu harapkan dari Aviduz yang menakutkan?",
  str_mission_desc_4008120 = "Jalan menuju jembatan dipenuhi dengan bahaya, dan para Eclipsite berdatangan...",
  str_mission_desc_4008130 = "Maju terus, Schummer sudah dekat!",
  str_mission_desc_4008140 = "Akhirnya, momen penentuan datang. Lumopolis dan Black Colossus. Hari ini, salah satunya akan jatuh dan kamu harus menyaksikan semua itu...",
  str_mission_desc_4009020 = "Kamu mengikuti jejak puing-puing Aviduz dan tiba di Eraveil, tempat semuanya dimulai.",
  str_mission_desc_4009030 = "Mungkinkah ada seseorang di sini selain Eclipsite?",
  str_mission_desc_4009040 = "Bahaya yang makin besar dan suatu wajah yang tidak asing telah menanti...",
  str_mission_desc_4009041 = "Cari kelemahannya dan gunakan untuk mengalahkan musuh.",
  str_mission_desc_4009050 = "Dengan bergabungnya Sinsa ke dalam tim, penjelajahan Eraveil menjadi tugas yang jauh lebih mudah.",
  str_mission_desc_4009060 = "Darkflow yang berlimpah ini mungkin membuat hawa menjadi dingin, tetapi kamu harus melanjutkan perjalanan.",
  str_mission_desc_4009070 = "Suasana mendadak mencekam. Dari mana asal jeritan itu? Apa itu suara Eclipsite?",
  str_mission_desc_4009090 = "Tanah berguncang dan sebuah aura yang menakutkan melonjak keluar...",
  str_mission_desc_4009100 = "Gunakan kemampuan psikismu untuk terus maju dan cari cara untuk menerobos formasi musuh!",
  str_mission_desc_4009110 = "Musuh seolah-olah keluar dari dinding, dan mereka beraksi secara serempak.",
  str_mission_desc_4009111 = "Jika kamu tidak bisa mengalahkan musuh dengan konfrontasi langsung, cobalah melakukannya dari sudut lain.",
  str_mission_desc_4009120 = "Sesosok lawan yang berat telah muncul... Sudah saatnya menyingkirkan kejahatan dari Eraveil!",
  str_mission_desc_4009130 = "Sesosok musuh yang lebih kuat sudah menantimu. Sebelum menghadapi pertempuran yang mengadang, kamu harus melarikan diri dari serbuan Eclipsite...",
  str_mission_desc_4009140 = "Reruntuhan Aviduz ada di depanmu! Namun, siapa yang berdiri di depannya?",
  str_mission_desc_4010020 = "Aviduz sudah di depan mata. Mengejar Forsakin, mengonfirmasi apakah Schummer masih hidup... apa pun yang terjadi nanti, tak ada pilihan lain selain masuk ke dalamnya...",
  str_mission_desc_4010030 = "Dengan kemampuan psikismu, kamu menyimpulkan bahwa Schummer telah... memakan Eclipsite!?",
  str_mission_desc_4010040 = "Rupanya tidak semua Eclipsite lari untuk menyelamatkan diri—beberapa bersiap untuk bertarung sampai mati.",
  str_mission_desc_4010041 = "Jika kamu mengalami kesulitan, coba manfaatkan area sekitar untuk mencari peluang!",
  str_mission_desc_4010050 = "Eclipsite yang tak terhitung jumlahnya berkeliaran di dalam Aviduz, bak belatung tanpa tujuan di dalam mayat yang bernanah.",
  str_mission_desc_4010060 = "Para Eclipsite itu kelihatannya sanngat ingin menghalangimu.",
  str_mission_desc_4010070 = "Sesosok musuh yang tidak asing pun muncul. Rupanya sihir kebangkitan Forsakin tidak bisa dianggap enteng...",
  str_mission_desc_4010090 = "Setelah memastikan kebenaran mimpimu tentang Eraveil, kemarahanmu pun tersulut sekali lagi.",
  str_mission_desc_4010100 = "Musuh yang berdiri di hadapanmu sepertinya mampu menyegel Luminatics! Ini akan menjadi pertempuran yang sengit.",
  str_mission_desc_4010110 = "Para Eclipsite yang menghalangimu pantang menyerah sebelum bertarung.",
  str_mission_desc_4010111 = "Sepertinya kemunculan para Eclipsite ini tidak ada habisnya...",
  str_mission_desc_4010120 = "Para Eclipsite itu mencoba membuatmu terpojok!",
  str_mission_desc_4010130 = "Schummer ada di depan. Tanpa menggunakan kemampuan psikismu pun kamu sudah mengetahuinya—tanah yang bergetar dan Darkflow yang tak terkendali sudah cukup menjadi bukti.",
  str_mission_desc_4010140 = "Kalahkan Schummer!",
  str_mission_desc_4101020 = "Tercekik oleh Darkflow, kesulitan yang kamu hadapi dalam pertempuran semakin meningkat. Namun, demi menyelamatkan Soroz, kamu tidak boleh ciut!",
  str_mission_desc_4101030 = "Di pelosok Undercity, jejak peperangan terkubur dalam-dalam bersama dengan rahasia lainnya…",
  str_mission_desc_4101040 = "Bagaimana bisa High-Level Eclipsite masuk ke sini? Lari! Jangan berhenti!",
  str_mission_desc_4101060 = "Reinhardt mengawasimu selama ini. Untuk memastikan kamu selamat sepanjang waktu, dia tenggelam dalam kecemasan dan kekhawatiran.",
  str_mission_desc_4101070 = "Apa yang terjadi di Undercity 80? Mungkin Reinhardt tahu jawabannya.",
  str_mission_desc_4101080 = "Dalam waktu dekat, kamu akan mendarat. Akankah ada harapan untuk kembali dengan selamat?",
  str_mission_desc_4101090 = "Kebencian yang terpendam lama tak dapat diredakan dengan mudah. Terkadang, pergi adalah pilihan terbaik.",
  str_mission_desc_4201020 = "Soroz disergap Eclipsite? Jangan panik. Kita akan mengenyahkan mereka dari Colossus!",
  str_mission_desc_4201030 = "Kalau Eclipsite berhasil menyerang Soroz, berarti ada seseorang yang jadi dalangnya. Ini bukan penyergapan biasa!",
  str_mission_desc_4201040 = "Bagaimanapun, tidak bisa dibilang jatuh kalau memang mendarat di tempat yang seharusnya.",
  str_mission_desc_4201041 = "Bertemu dengan Eclipsite saat mencari jalan masuknya bukanlah bagian dari rencana. Tapi, jangan buang-buang waktu. Ayo cepat kita habisi mereka.",
  str_mission_desc_4201050 = "Untung kamu membawa detektor logam itu sehingga pencarian jalan masuknya berjalan mulus. Tapi, apa benda itu bisa menemukan sesuatu yang berguna?",
  str_mission_desc_4201060 = "Tempat ini kosong... Yang tersisa hanyalah gema dan peninggalan masa lalu.",
  str_mission_desc_4201061 = "Teruslah menjelajah dan mencari... Ayo kita berusaha sebaik mungkin untuk menemukan cahaya harapan di kedalaman.",
  str_mission_desc_4201070 = "Ada sosok misterius yang mengawasi pertempuran ini, ia mengikuti setiap gerak-gerikmu.",
  str_mission_desc_4201080 = "Jangan berhenti dan jangan menoleh. Teruslah berlari ke depan dan mencari hikmahnya.",
  str_mission_desc_4201090 = "Kejahatan macam apa yang seseorang lakukan sampai-sampai ia diasingkan ke jurang semacam itu?",
  str_mission_desc_4201100 = "Tidak ada di sini, tapi di tempat yang lebih dalam. Teruslah maju, tapi waspadai ancaman dari masa lalu.",
  str_mission_desc_4201120 = "Caelestite, Aurorian, Eclipsite, Colossus... Aku ingin tahu berapa banyak rahasia yang tersembunyi di pangkalan luas yang terbengkalai sejak lama ini...",
  str_mission_desc_4201130 = "Bukan hanya dinding dan gerbang pangkalan saja yang menjaga rahasia-rahasia ini, melainkan juga para Eclipsite di sini.",
  str_mission_desc_4201140 = "Karena Neural Aux itu sudah rusak, tak ada cara untuk memasukkan perintah dengan benar. Bagaimana kalau... melakukan reboot dulu?",
  str_mission_desc_4202020 = "Sepertinya ada Eclipsite di menara ini. Apa mereka memang sudah ada di sini sejak dulu?",
  str_mission_desc_4202030 = "Seiring dengan berlanjutnya perjalananmu, kamu menjumpai sesuatu yang misterius dan tak terduga.",
  str_mission_desc_4202040 = "Kamu mendengar suara-suara aneh di belakangmu sejak tadi. Apa ada Eclipsite yang mengikutimu... atau justru sesuatu yang lain?",
  str_mission_desc_4202041 = "Sejak kapan Eclipsite jadi pintar dan bisa menggunakan perangkap?! Waspadalah, ayo kita kalahkan mereka!",
  str_mission_desc_4202050 = "Kenapa ada banyak perangkap yang mengarah ke Chord Zone?! Aku jadi penasaran apa benda ini bisa dimanfaatkan...",
  str_mission_desc_4202060 = "Barton memutuskan untuk menggunakan Chord Link agar bisa melarikan diri dari situasi sulit ini. Berusahalah mengulur waktu agar dia bisa kabur!",
  str_mission_desc_4202070 = "Tetap tenang... Sebentar lagi situasinya akan berbalik menguntungkanmu.",
  str_mission_desc_4202090 = "Pertempuran berkobar di luar menara, dan bala bantuan sudah datang. Sekarang, yang tersisa hanyalah pertarungan.",
  str_mission_desc_4202100 = "Semua orang berjuang sekuat tenaga di pertempuran, tapi berapa lama mereka bisa bertahan?",
  str_mission_desc_4202115 = "Aurorian di luar Obelisk of Return berusaha sebaik mungkin untuk mencari peluang yang bisa mengubah keadaan.",
  str_mission_desc_4202111 = "Sepertinya si pembuat onar itu sudah memasuki pertempuran. Waktu hampir habis. Sekarang, ayo serang!",
  str_mission_desc_4202120 = "Masih ada Eclipsite yang menutup jalur ke Core Ring dan tantangan yang lebih berat di depan sana.",
  str_mission_desc_4202130 = "Ada beberapa hal yang hanya bisa dilakukan olehmu. Semua orang sudah di sini dan siap membantu. Lakukan saja.",
  str_mission_desc_4202140 = "Ini adalah panggilan untuk kembali, bukan hanya untukmu, tapi juga untuk harapan.",
  str_mission_desc_4203020 = "Untuk lebih memahami kondisi Vice, Anda setuju untuk mengizinkan Illumina meneliti modul data baru yang ditemukan di Soroz.",
  str_mission_desc_4203030 = "Setelah memasuki medan simulasi, Anda mulai melakukan tes sesuai dengan instruksi peneliti. Paling tidak, pertarungannya cukup mudah... untuk saat ini.",
  str_mission_desc_4203040 = "Anda menggunakan simulator pertempuran sekali lagi, tetapi kali ini medan dan lingkungan telah berubah.",
  str_mission_desc_4203041 = "Ada kekacauan dan bahaya di sekitar, dan Anda benar-benar tersesat... Anda tidak bisa tinggal di sini lebih lama lagi!",
  str_mission_desc_4203050 = "Tunggu sebentar. Tidak ada yang bilang simulasinya akan sesulit ini!",
  str_mission_desc_4203060 = "Tempat apa ini? Mengapa saya belum pernah melihatnya sebelumnya? Keburukan? Reinhardt? Bisakah kalian mendengarku?",
  str_mission_desc_4203070 = "Tentara yang putus asa dihancurkan di bawah serangan Eclipsite yang biadab... Apakah ini akhir dunia?",
  str_mission_desc_4203090 = "Penjaga Satu, yang bertanggung jawab atas keseluruhan operasi harian Federasi Illumina... terlihat lebih kecil dari yang diharapkan.",
  str_mission_desc_4203100 = "Meskipun ini pertama kalinya Anda bertemu Guardian One, rasa percaya yang murni dan alami terjalin di antara Anda berdua.",
  str_mission_desc_4203110 = "Tidak mungkin berdiri dengan kedua kaki di tanah yang kokoh di lingkungan virtual. Meski begitu, satu-satunya pilihan Anda adalah terus maju.",
  str_mission_desc_4203111 = "Eksperimen ini berupaya menguji batas kekuatan seseorang untuk menemukan peluang sekecil apa pun untuk menembusnya.",
  str_mission_desc_4203120 = "Ulurkan tangan Anda, lari lebih cepat—Anda hanya selangkah lagi untuk meraihnya.",
  str_mission_desc_4203130 = "Sudah waktunya untuk memperbaiki hal-hal. Bagaimanapun, itulah mengapa Anda datang ke sini sejak awal.",
  str_mission_desc_4203140 = "Setelah waktu yang tidak ditentukan, Anda akhirnya sampai pada kesalahan terakhir.",
  str_mission_desc_4204020 = "Senjata kuat dan penting yang dikenal sebagai \"Combat Cyborg\" sebenarnya...",
  str_mission_desc_4204030 = "Sean kembali dari zona perang secepat mungkin. Dia menerima kabar dari garnisun Illumina bahwa Anda sedang dalam perjalanan.",
  str_mission_desc_4204031 = "Terkadang, menyerbu langsung ke pertempuran bukanlah pilihan terbaik.",
  str_mission_desc_4204040 = "Anda melanjutkan perjalanan Anda ke Twilight, di mana tiga teman lama akhirnya dipertemukan kembali.",
  str_mission_desc_4204050 = "Setelah akhirnya mencapai pinggiran Twilight, aurora di atas kepala mulai melonjak tak terkendali, menimbulkan bencana bagi mereka yang tinggal di bawahnya.",
  str_mission_desc_4204060 = "Masih ada warga sipil di belakang Anda yang mencoba melarikan diri! Jangan biarkan satu pun Eclipsite melewati Anda!",
  str_mission_desc_4204070 = "Seberkas cahaya tiba-tiba menerangi medan perang, memungkinkan Anda dan sekutu Anda untuk bertarung tanpa kendala.",
  str_mission_desc_4204090 = "Anda dan sekutu Anda akhirnya siap. Kegelapan tidak akan lagi menghalangi pandangan Anda.",
  str_mission_desc_4204100 = "Apa yang Anda cari... Di mana itu?",
  str_mission_desc_4204101 = "Temukan titik lemah, bidik dengan baik, dan konsentrasikan seranganmu!",
  str_mission_desc_4204115 = "Siapa yang lebih kuat: Axelia atau Sean?",
  str_mission_desc_4204120 = "Setelah kesulitan yang tidak sedikit, Anda akhirnya menemukan Colossus yang mendarat di reruntuhan. Kemenangan hanya dalam jangkauan.",
  str_mission_desc_4204130 = "Segera setelah menyalin datanya, Colossus mulai bergerak. Mungkinkah bencana lain sudah dekat?",
  str_mission_desc_4204140 = "Sebuah puisi terakhir, dipersembahkan atas namamu... Sebuah perpisahan terakhir.",
  str_mission_desc_4205020 = "Anda dipaksa oleh Forsakin untuk melawan tentara Illumina.",
  str_mission_desc_4205030 = "Anda sekali lagi bertemu penjaga di pintu masuk lab.",
  str_mission_desc_4205040 = "Anda dan Vice tidak akan mengutak-atik ibu jari Anda saat eksperimen berlangsung. Tunggu waktu yang tepat untuk membalikkan keadaan...",
  str_mission_desc_4205041 = "Raih kesempatan untuk mengalahkan musuh dan melarikan diri!",
  str_mission_desc_4205050 = "Perlawanan Anda adalah Eclipsites yang dipanggil oleh Forsakin dalam duel sengit sampai mati!",
  str_mission_desc_4205070 = "Terpisah dari Vice, diri Anda sendiri tidak punya pilihan selain mematuhi Forsakin. Anda harus mengikuti keinginannya dan menjelajah jauh ke dalam Undercity.",
  str_mission_desc_4205080 = "Untuk menemukan Anda dan Vice, yang telah lama hilang, Carleen mengikuti tip Gronru ke Undercity.",
  str_mission_desc_4205090 = "Masih mencari file, Forsakin tidak mengharapkan pertahanan tajam di Arsip File.",
  str_mission_desc_4205100 = "Ditugaskan dengan misi penting, Yingel akhirnya menemukan keberadaan Vice, hanya untuk bertemu dengan musuh yang tangguh sebelum penyelamatan...",
  str_mission_desc_4205101 = "Beberapa musuh akan melibatkan Anda dalam pertarungan yang panjang dan mematikan, jadi berhati-hatilah...",
  str_mission_desc_4205110 = "Yingel berjuang pertempuran yang sulit, sementara Carleen telah berhasil mencapai Forsakin dan akan mencoba mengeluarkanmu dari sini.",
  str_mission_desc_4205120 = "Forsakin dibuat tidak seimbang oleh kobaran api yang tiba-tiba. Ambil kesempatan untuk mengalahkannya dan Helios!",
  str_mission_desc_4205130 = "Tepat ketika Anda akan mengalahkan Forsakin, dia menggagalkannya dengan memutus aliran listrik ke gerbang utama ...",
  str_mission_desc_4205140 = "Forsakin telah menyelesaikan peningkatan terakhir ke Helios. Ini akan menjadi pertarungan brutal.",
  str_mission_desc_4206020 = "Sesi pertama adalah pertarungan virtual melalui Battle Simulator, dan semua peserta latihan mempersiapkannya dengan serius.",
  str_mission_desc_4206030 = "Sesi kedua adalah pelajaran tempur, dengan tim staf pelatihan yang dipimpin oleh Wrath menularkan ilmu tawuran kepada peserta latihan...",
  str_mission_desc_4206040 = "Untuk lebih banyak kredit kursus, Anda, Vice, Dan Carleen memutuskan untuk mengajukan izin simulator tambahan untuk mengasah keterampilan tempur Anda.",
  str_mission_desc_4206041 = "Musuh tampaknya memberi makan pertempuran! Harus ada cara untuk mengakhiri perjuangan!",
  str_mission_desc_4206050 = "Sebelum latihan dimulai, Eclipsites entah dari mana tiba-tiba muncul di Gannon City. Singkirkan mereka sesegera mungkin.",
  str_mission_desc_4206060 = "Sesi ketiga Latihan Militer Gabungan adalah melawan Eclipsites asli dalam pertempuran nyata. Akankah para peserta menang melawan begitu banyak musuh?",
  str_mission_desc_4206070 = "Setelah mencapai lokasi untuk menangkap bendera, regu berpencar dan pergi ke Undercity. Namun, pasukan Anda terlibat pertarungan tak terduga melawan Eclipsites.",
  str_mission_desc_4206080 = "Pertarungan kacau berlanjut dan pasukan aneh itu terbukti cukup tangguh...",
  str_mission_desc_4206090 = "Anda menggali lebih jauh ke dalam Undercity hingga tiba-tiba menghadapi bahaya yang lebih besar dalam bentuk monster raksasa mirip laba-laba.",
  str_mission_desc_4206110 = "Anda, Yingel, dan yang lainnya berpisah untuk memeriksa Gannon. Benar saja, Anda bertemu dengan Eclipsites yang lolos dari celah pertahanan!",
  str_mission_desc_4206120 = "Para penyusup Eclipsite berhamburan panik, tampaknya tidak berniat untuk melawan. Anda juga merasakan ancaman familiar dari Wraith tertentu...",
  str_mission_desc_4206121 = "Penyusup masih ada di kota yang harus dibasmi secepatnya.",
  str_mission_desc_4206130 = "Mengikuti jejak Wraith, Anda sampai di gerbang tertentu di tingkat terendah. Figerald mencari sesuatu di sana. Hentikan dia!",
  str_mission_desc_4206140 = "Peon semua keluar dari jalan. Sekarang ke Figerald the Wraith!",
  str_mission_desc_4207020 = "Kamu dan Vice tiba di kantor Illumina Legion Commanders, berharap untuk mendapatkan kesempatan mengubah keadaan. Namun, sebelum kamu bisa bicara, para komandan sudah menerima perintah misi dan pergi...",
  str_mission_desc_4207030 = "Warga Illumina sedang ramai membahas kejadian-kejadian baru-baru ini. Saat kamu menyadari hal ini, sebuah pengumuman terdengar melalui siaran Undercity, yang mengumumkan kenaikan jabatan seorang Grand Marshal baru...",
  str_mission_desc_4207031 = "Eclipsite akan segera lolos dari tempat mereka terkurung. Kalahkan mereka demi keamanan laboratorium!",
  str_mission_desc_4207040 = "Baru saja dipromosikan menjadi Grand Marshal di Illumina, Wrath sudah ditugaskan untuk memperkuat garis depan pertempuran di Twilight. Namun, saat dia bersiap untuk berangkat, sepertinya dia tidak merasakan kebahagiaan yang diharapkan dari menjadi Grand Marshal...",
  str_mission_desc_4207050 = "Merefleksikan masa lalu, Wrath telah memulai banyak tantangan melawan Reinhardt, hampir semua berakhir dengan kegagalan, termasuk seleksi terakhir untuk Grand Marshal...",
  str_mission_desc_4207060 = "Joselyne membawa orang-orang yang terluka menuju tempat yang aman. Namun, setelah mengetahui kepercayaan diri prajurit yang goyah di medan perang, dia merenungkan apa yang bisa dia lakukan untuk mereka...",
  str_mission_desc_4207080 = "Dengan kemampuan psikismu, kamu merasakan bahwa darkflow yang merajalela di Twilight tampaknya dikendalikan oleh suatu pusat komando. Namun, musuh utama di pusat ini masih terbungkus misteri...",
  str_mission_desc_4207090 = "Kedatangan prajurit Illumina sementara menghentikan aksi para Eclipsite, namun Forsakin tampaknya telah mendeteksi rahasia di balik kekuatan prajurit-prajurit ini yang ditingkatkan...",
  str_mission_desc_4207100 = "Saat pertempuran melawan Eclipsites terus berlangsung, gelombang tindakan abnormal menyebar di antara prajurit Illumina. Spekulasi berkembang bahwa para prajurit mungkin dipengaruhi oleh musuh yang bertindak sebagai komando pusat...",
  str_mission_desc_4207110 = "Kuatir untuk Axelia di medan perang, Yingel menuju ke laboratorium Ulysses. Di dalam tembok ini, dia menyaksikan eksperimen kejam...",
  str_mission_desc_4207111 = "Monster di rawa-rawa telah menghalangi jalanmu. Kalahkan mereka!",
  str_mission_desc_4207120 = "Menghadapi rawa yang terus meluas dan serangan Eclipsite, Wrath membuat keputusan tegas—untuk terjun ke dalam lumpur, mencari musuh komando pusat yang bersembunyi di dalamnya...",
  str_mission_desc_4207130 = "Setelah bentrok dengan musuh komando pusat, tubuh Wrath perlahan-lahan kehilangan kendali. Soroz menduga bahwa kesadarannya telah ditelan oleh lumpur...",
  str_mission_desc_4207140 = "Pasukan Axelia telah terperangkap dalam lumpur cukup lama. Pada saat ini, Axelia sudah kehilangan kemampuan untuk menyerang Eclipsites, tetapi bibirnya terus menggumamkan dua perintah aksi khusus...",
  str_mission_desc_4208020 = "Setelah Eclipsite lumpur berhasil dikalahkan, kamu memulai pencarian total untuk menemukan lokasi Wrath. Namun, pada saat yang sama, perubahan tak terduga juga mulai muncul di antara prajurit Illumina...",
  str_mission_desc_4208030 = "Rasa lega menyelimuti Anda saat Wrath kembali, namun pengalaman yang dialaminya membuat Anda bingung. Selanjutnya, fokus bersama beralih untuk menangani situasi prajurit yang terluka...",
  str_mission_desc_4208040 = "Tim pelacak yang dipimpin oleh Charon dan Vice menghadapi perlawanan yang aneh, yang menghalangi mereka untuk mencapai Dark Zone. Sementara itu, di dalam kereta, muncul seorang penumpang misterius...",
  str_mission_desc_4208041 = "Kondisi semakin di luar kendali. Musuh kini mengincar Anda; tolong lindungi rekan satu tim Anda.",
  str_mission_desc_4208050 = "Victoria berhasil membawa kelompok ini untuk menghindari kejaran pasukan misterius untuk sementara waktu. Namun, pada saat yang sama, Bloody Bible mengungkapkan wahyu baru...",
  str_mission_desc_4208060 = "Saat Wrath mencari bawahannya, seorang prajurit yang bingung mencekik lehernya. Semua orang mencoba membujuknya, tetapi dia masih belum bisa memutuskan...",
  str_mission_desc_4208070 = "Joselyne memohon Benteng Lumo untuk melindungi para pengungsi, tetapi hanya mendapat penolakan. Namun, ketika prajurit yang terluka mulai menyerang orang yang tidak bersalah, suara yang kuat bergema...",
  str_mission_desc_4208080 = "Saat operasi pencarian mencapai batas Twilight, pemandangan mengejutkan terbentang di depan mata kelompok ini. Dan dalang di balik semuanya, pada akhirnya, akhirnya muncul...",
  str_mission_desc_4208100 = "Dengan menghilangnya lumpur, Twilight hanya menyisakan dinding-dinding yang hancur dan reruntuhan. Namun, menghadapi puing-puing yang berantakan ini, Leo dan Joselyne tampaknya memiliki harapan baru untuk masa depan kota ini.",
  str_mission_desc_4208110 = "Di sepanjang garis pertahanan Illumina, Sharona memimpin 1st Legion, berusaha untuk mengusir Eclipsites. Namun, banjir lumpur mendadak dan serangan dari sesama prajurit memicu kepanikan di antara barisan...",
  str_mission_desc_4208111 = "Bersihkan rawa-rawa dengan bala bantuan artileri!",
  str_mission_desc_4208120 = "Saat Forsakin memimpin rawa-rawa dalam serangan ke garis pertahanan Illumina, suara paduan roda bergemeretak dan kaki berkuda bergema dari arah Twilight...",
  str_mission_desc_4208130 = "Pertempuran sengit terus berlanjut, dengan tentara Illumina yang bingung melancarkan serangan tanpa henti terhadap pihak Anda...",
  str_mission_desc_4208140 = "Saat para komandan Illumina menganalisis situasi saat ini, Forsakin, setelah menerima sinyal mundur dari Eclipse, bertekad untuk memberikan pukulan terakhir kepada prajurit Illumina...",
  str_mission_desc_4001010_long = [[
Kamu tidak bisa mengaktifkan Colossus meskipun sudah mencobanya selama lebih dari 17 tahun dengan sia-sia.
Vice, seorang gadis Aurorian, tiba-tiba muncul di Colossus saat kamu mencobanya lagi.
Vice berjanji akan mengeluarkanmu dari sini saat kamu mengalahkan Eclipsite dengan kemampuan psikismu.
Akankah kamu berhasil keluar dari Colossus?]],
  str_mission_desc_4001020_long = [[
Kamu mengalahkan Eclipsite dengan kekuatanmu lagi.
Kamu sekarang berteman dengan tim Vice--
Sulit dipercaya kamu bisa berteman, bahkan sebelum keluar ke dunia lain.]],
  str_mission_desc_4001030_long = [[
Karena komunikatornya rusak, kamu kalah jumlah oleh Eclipsite tanpa bantuan.
Mungkin semua orang bisa selamat kalau kamu mengaktifkan Starlight Chamber.]],
  str_mission_desc_4001045_long = [[
Kamu kehilangan kesadaran karena terlalu banyak menggunakan kemampuan psikismu untuk mengendalikan Colossus.
Aurorian lain, Ms. Blanc, bergabung sebagai bala bantuan.
Namun, penanda sinyal telah menarik sejumlah Eclipsite.
Kamu harus mulai bergerak dan mencari jalan keluar.]],
  str_mission_desc_4001050_long = [[
Kamu menemukan objek target Charon, seorang insinyur bernama Zoya di stasiun pangkalan dalam waktu singkat.
Selain Zoya, seorang pemuda masih hilang.
Karena tak bisa tinggal diam, kamu melewati sekelompok Eclipsite untuk mencarinya.
Untungnya, dia masih hidup!
Hanya saja dia terluka dan "dia" sebenarnya adalah seorang gadis.]],
  str_mission_desc_4001060_long = [[
Akhirnya, kamu memasuki Undercity 28.
Charon membawamu dan orang luar masuk, meskipun dia cukup keras.
Setelah mengalahkan orang-orang yang melarikan diri, kamu bertemu Soroz di pelabuhan.
Walau sumber daya di undercity terbatas, Colossus diisi ulang dan perlahan pulih.
Karena bisa beristirahat, kamu merasa lega lalu... pingsan.]],
  str_mission_desc_4001070_long = [[
Kamu dan Aurorian bersama-sama mengalahkan High-level Eclipsite Kraken.
Ini bukanlah waktu yang tepat untuk merayakannya karena pasukan kuat Eclipsite sedang menunggumu.
Untuk evakuasi yang aman dan untuk mengunjungi dunia baru...
Vice memutuskan untuk mencoba mengaktifkan kembali Colossus bersamamu.]],
  str_mission_desc_4001095_long = "Kamu dan Vice bersama-sama mengendalikan Colossus. Saat mesin menyala... Soroz, yang diselimuti Aurora, benar-benar terbangun.",
  str_mission_desc_4001080_long = [[
Soroz perlu pemanasan setelah tertidur selama 17 tahun.
Namun, kamu berdaya di hadapan para Eclipsite.
Melindungi Colossus adalah prioritas utama!]],
  str_mission_desc_4001090_long = [[
Operasi penyelamatan yang mustahil itu terlalu sulit.
Jangan pernah pergi dan jangan pernah menyerah. Bisakah kamu melakukannya?
Suara ledakan yang jauh itu membuatmu dan Vice tidak nyaman.
Apa yang terjadi di sisi Charon?]],
  str_mission_desc_4001100_long = [[
Ketidaknormalan makin dekat dari tempat Charon.
Bergegaslah ke tempat tujuanmu dan bersiaplah untuk bertarung melawan lawan yang tangguh!
Charon dan Dayna dalam kondisi prima. Kalian semua bersatu kembali!
Ada secercah harapan di tengah keputusasaan:
Soroz berlabuh di pelabuhan terdekat.]],
  str_mission_desc_4001110_long = [[
Soroz, sebuah harapan dalam kesulitan, 
akan membantumu melarikan diri.
Tak seorang pun tahu apakah ada tantangan yang lebih besar nanti.
Tak ada waktu untuk membebani dirimu dengan kesulitan yang tak terduga. Lindungi orang-orang yang terluka dan rekanmu untuk membantu mereka menaiki Colossus sekarang.
Beradaptasilah!]],
  str_mission_desc_4001120_long = [[
Kamu terluka parah oleh serangan dahsyat Eclipsite.
Beberapa rekanmu tumbang dalam pertempuran, sementara yang lain berjuang mati-matian untuk hidup.
Pertempuran yang berat telah menantimu.]],
  str_mission_desc_4001130_long = [[
Soroz pergi seperti dugaan semua orang.
Namun, High-level Eclipsite lainnya, Nozard, muncul di Colossus.
Semua terlalu lelah untuk bertarung karena pertempuran yang tak ada habisnya.
Beberapa temanmu mengorbankan nyawa mereka agar yang lain bisa tetap hidup...]],
  str_mission_desc_4002015_long = [[
Karena kalian semua telah lolos dari bahaya untuk saat ini, Vice meyakinkanmu untuk kembali ke Illumina bersamanya terlebih dahulu.
Saat kamu ragu-ragu, Soroz, yang sudah tidak digunakan selama lebih dari 17 tahun, terpaksa mendarat karena tidak berfungsi.
Di sisi lain, Nozard selamat dan tak berhenti memburumu...]],
  str_mission_desc_4002010_long = [[
Suara keras dari Colossus yang jatuh menarik perhatian Eclipsite yang tak terhitung jumlahnya. 
Pertempuran baru akan datang.]],
  str_mission_desc_4002035_long = [[
Vice terluka parah karena melindungimu dari Eclipsite saat kamu berdebat dengannya.
Di saat yang genting, sekelompok perampok yang mengaku sebagai anak buah Sinsa mengalahkan Eclipsite.
Kamu selamat, tetapi mereka mengaku sebagai pemilik Colossus.]],
  str_mission_desc_4002020_long = [[
Pertempuran lain akan datang. Namun, kamu harus mengandalkan orang-orang Rediesel Wrench yang tidak dikenal.
Ternyata para bandit ini bisa bertarung seperti Aurorian!]],
  str_mission_desc_4002030_long = [[
Pertempuran lain akan datang. Namun, kamu harus mengandalkan orang-orang Rediesel Wrench yang tidak dikenal.
Ternyata para bandit ini bisa bertarung seperti Aurorian!]],
  str_mission_desc_4002040_long = [[
Apakah Sinsa melakukannya di saat lemah atau punya alasan lain?
Kamu hanya bisa melihat apa yang akan terjadi selanjutnya.
Dia membawamu ke markas Rediesel Wrench.
Jalan ini, Tail Street, penuh dengan keputusasaan dan kejahatan.
Mengapa dia membawamu ke sini?]],
  str_mission_desc_4002050_long = [[
Dunia memiliki hierarki dan selalu ada sudut gelap yang tidak pernah kamu ketahui.
Faktanya adalah kamu dan Vice memiliki pemahaman baru tentang Rediesel Wrench...
Setidaknya kamu tahu salah satu tujuan Sinsa: 
Mereka ingin membersihkan nonstarter dengan bantuan Soroz.]],
  str_mission_desc_4002060_long = [[
Pertempuran dimulai, tetapi semua orang bertanya-tanya mengapa Eclipsite bisa bertarung dengan sengaja dan organis.
Kehadiran Umbrahulk membuktikan bahwa mereka memang benar!
Saat bala bantuan Illumina tiba, orang-orang Rediesel Wrench pergi dengan bijaksana. 
Sekali lagi, nasibmu ditentukan oleh orang lain.]],
  str_mission_desc_4002095_long = [[
Kamu kembali ke Undercity 28 bersama Charon. Vice dan Soroz aman.
Pertahanannya tidak bisa ditembus, tetapi Charon dan Hiiro masih menduga bahwa Eclipsite tahu cara untuk menyeberanginya.
Beberapa hari kemudian, Vice pulih. Istirahat singkatnya terganggu oleh krisis baru --
Undercity mulai bergetar dan alarm dinyalakan. Apa yang terjadi?!]],
  str_mission_desc_4002070_long = "Eclipsite menembus pertahanan di sudut undercity yang tersembunyi, dan semuanya dalam bahaya.\nCara terbaik untuk melindungi orang-orang yang terluka dan para warga adalah dengan mundur. Kamu hanya bisa menjalankan rencana darurat.\nBeberapa misteri tersembunyi di balik semua ini, tetapi kamu tidak punya waktu untuk memikirkannya—",
  str_mission_desc_4002080_long = [[
Sinsa dan Eve pernah tinggal di undercity sebelumnya.
Eve juga dipandang "sebelah mata" di sana.
Apa yang sebenarnya terjadi?
Apa yang bisa diceritakan sejarah kepada kita?
Sekarang, kamu hanya bisa terus mengikuti jejak Sinsa dan memenuhi dua permintaannya...]],
  str_mission_desc_4002090_long = [[
Kamu dikepung dengan bergelombang-gelombang serangan dari Eclipsite.
Jika terus seperti ini, semua orang akan berada dalam bahaya besar!
Karena pernah menghadapi masalah yang sama, kamu memiliki sebuah ide: Colossus adalah harapan terakhir.]],
  str_mission_desc_4002100_long = [[
Eclipsite berkumpul di sekitar Colossus. Sebaiknya kamu mundur dan menghancurkan semua info undercity secepat mungkin.
Namun, sekarang belum waktunya untuk menekan Red Key!]],
  str_mission_desc_4002110_long = [[
Semua orang ada di Colossus, kecuali Charon.
Meskipun tak bisa meninggalkan Charon seperti itu, kamu sudah sangat lemah.
Tak ada pilihan lain selain meninggalkannya...]],
  str_mission_desc_4002120_long = [[
Red Key sudah ditekan. Mundur sekarang!
Kamu berhasil mengalahkan Nozard, yang bangkit lagi, untuk selamanya ketika menerobos kepungan dan kabur.
Asap mengepul di Undercity 28. Ketika kamu sedang berduka atas Charon...
Sebuah kereta terbang tinggi dari arah api; apakah itu Charon?!]],
  str_mission_desc_4003015_long = [[
Sebelum bala bantuan tiba, kamu mendengar teriakan dari seorang pemuda. Apa dia kaummu?
Kamu berusaha mencari celah untuk mengungkap kebenaran meski itu berbahaya!
Vice memutuskan untuk menemanimu kali ini. Caelestite tidak perlu bertarung sendirian.]],
  str_mission_desc_4003010_long = [[
Sebuah prasasti yang baru dibangun berdiri di tebing saat matahari bersinar seperti biasa.
Baik kamu maupun Sinsa tidak dapat melepaskan diri dari kerinduan.
Perubahan baru mengejutkanmu. Pasukan Illumina memecah keheningan.
Vice dan kamu kembali ke tim setelah menangani serangan Eclipsite yang tak terduga
Orang-orang Rediesel Wrench pergi, menghilang ke belantara...]],
  str_mission_desc_4003020_long = [[
Mendelson, orang yang melindungi Think Tank Module, diserang oleh Schummer
Meski berusaha untuk memberontak, tubuhnya yang tercabik-cabik dan penuh luka tidak bisa mengubah nasibnya.
Tanpa para prajurit, dia terpaksa mundur dan hanya bisa meminta bantuanmu saat meloloskan diri.]],
  str_mission_desc_4003030_long = "\"Waktu habis,\" teriak sesosok pemuda misterius yang mencari bantuan.\nPenggalian Colossus di ES-0096-F7 Relic tiba-tiba terhenti. Hiiro juga menghilang.\nKamu dan Vice dengan terpaksa mengaktifkan Colossus untuk mencari atasanmu.\nTak hanya untuk membuktikan kecakapanmu untuk mengepalai Colossus, \ntetapi lebih untuk menyelamatkan kawanmu.",
  str_mission_desc_4003031_long = "TBC",
  str_mission_desc_4003040_long = [[
Anggota tim penggalian bergabung dengan Eclipsite!
Kamu harus menyiapkan mental untuk melawan kawan lamamu.
Sementara itu, dinding api relik Aurorian mulai digerogoti kekuatan gelap.
Great Aviduz mengumumkan bahwa dengan kekuatan agungnya, dia akan membinasakan para pengkhianat dan membalaskan dendam Ibu.]],
  str_mission_desc_4003050_long = [[
Kamu tak akan bisa menyelamatkan penyintas terakhir. Darkening sudah ditakdirkan untuk berakhir seperti ini.
Hujan bunga mungkin menyelamatkan nyawanya...
Sakura membersihkan tubuhnya dan menanamkan keyakinan Aurorian ke dalam pikirannya.
Dia memberitahukan pesan penting, bahwa "mereka" masih ada di sini.]],
  str_mission_desc_4003060_long = "Akhirnya, Mendelson yang terluka parah pun berhasil ditemukan.\nDia ditangkap oleh prajuritnya sendiri karena kekuatan Schummer.\nPertempuran sudah dekat—",
  str_mission_desc_4003070_long = [[
Pertunjukan tampaknya berakhir secara diam-diam di tempat lain.
Meski begitu, Schummer ingin membawa pertunjukan tersebut ke klimaksnya lagi, untuk menyuntikkan Darkflow yang tak terhitung jumlahnya ke inti Colossus.
Vice merasakan sesuatu, meski masih samar-samar.
Kamu harus menggunakan telingamu. Secara intuitif, kamu mungkin bisa menemukan jalan menuju akhir pertunjukan.]],
  str_mission_desc_4003080_long = [[
Meskipun ketakutan, mati dengan terhormat lebih baik daripada hidup tercela.
Caelestite dimusnahkan. Mempertahankan masa depan semua orang adalah prioritas utama!
Schummer berhasil mendapatkan Think Tank Module. Sekarang hanya tinggal menunggu waktu sebelum...
Kamu harus maju untuk menuntaskan ini semua!]],
  str_mission_desc_4003090_long = "Sosok dalam pikiranmu kini berdiri di hadapanmu, tampak asing sekaligus familier.\nPemuda lemah itu ternyata ECHO dari relik Colossus, Mendelson.\nSementara itu, Hiiro dan Zoya terkubur puing-puing reruntuhan.\nTeriakan Colossus menggema keras di reruntuhan—\nMereka harus mempercepat langkah bila tidak ingin terkena reruntuhan kedua.",
  str_mission_desc_4003091_long = "TBC",
  str_mission_desc_4003100_long = [[
Sebagian besar sistem tidak berfungsi karena kerusakan yang ditimbulkan oleh Schummer.
Sulit menemukan lokasi Hiiro dan Zoya. Mereka terpaksa harus mencari cara untuk melarikan diri.
Kamu dan Vice harus pergi untuk menuntaskan 
misi yang lebih penting dengan Mendelson.]],
  str_mission_desc_4003110_long = [[
Kamu akhirnya sampai di tempat penyimpanan Think Tank Module, dan Schummer...
mungkin menantimu di sini.
Hentikan dia! Terkena pengaruh energi kegelapan membuat tubuh Mendelson makin lemah.
Mungkin... ini akan jadi pertarungan terakhirnya.]],
  str_mission_desc_4003120_long = "Schummer pergi, dan Tabaad menantimu di sana.\nBerkat bantuan Hiiro, tubuh Tabaad memudar dalam sakura.\nDengan visi terakhir, hidup Mendelson berakhir, meninggalkan petunjuk:\nThink Tank Module, Autonomous Growth Unit, dan Flame Control Module—inilah yang akan diincar Schummer berikutnya...",
  str_mission_desc_4003145_long = [[
Saat ini, di Lumopolis Archive, Think Tank Module terkunci di suatu tempat.
Orang-orang yang mengincarnya sudah mulai mendekat, yang jadi pertanda bahwa Eclipsite akan segera menyerang Lumopolis.]],
  str_mission_desc_4004015_long = [[
Sebuah kota besar yang melayang di udara sudah terlihat. Sepertinya incaranmu, Think Tank Module lain, ada di sana.
Musuh bebuyutanmu, Schummer, sudah mengetahui adanya Lumopolis. Keadaan tidak menguntungkan.
Prioritasmu adalah membujuk Guardian Kapten, Carleen.
Tiba-tiba, percakapanmu terpotong oleh serangan kejutan...]],
  str_mission_desc_4004010_long = "Menurut penduduk kota di Lower Lumopolis, mereka sering diserang oleh Eclipsite di daerah timur. Guardian pergi untuk menyelidikinya. Akan tetapi, kamu lebih memilih untuk memeriksa area barat karena insting Carleen. Agen yang ditempatkan di kota berbisik: Kami akan mendapatkan kebebasan yang sudah dijanjikan setelah mendapatkan benda itu.",
  str_mission_desc_4004020_long = [[
Eclipsite terlihat di area barat! Yang melarikan diri membangkitkan iblis di mana-mana.
Menurut Gertzurde, pemimpin skuadron Lower Lumopolis, penduduk di luar kota perlu dievakuasi.
Sepertinya dia dulunya adalah kesatria yang terkenal juga...]],
  str_mission_desc_4004030_long = [[
Koordinat yang diberikan Soroz mengarah ke Lumopolis Gardens, daerah yang dijaga ketat di Lumopolis.
Ketika Darkover tiba, 
Great Aviduz yang bersembunyi di kegelapan akan bergerak untuk mengambil Lumopolis Core.
Sebelum badai datang, kamu menyadari sesuatu yang besar akan terjadi...]],
  str_mission_desc_4004040_long = [[
Darkover mengubah Lumo Guard menjadi Eclipsite.
Makhluk semacam itu tak boleh ada di sini. Lower Lumopolis dalam bahaya!
Lumo Soldier mengusirmu saat memburu Shire di Lumopolis Garden.
Ini semua demi Core dan takdir Lumopolis, jadi 
Vice berusaha sekuat tenaga untuk membujuk Carleen, kapten Lumopolis Guardian, agar membantu misinya.]],
  str_mission_desc_4004050_long = [[
Ada yang datang dari area barat! Sepertinya Eclipsite Level Tinggi!
Lacak dan singkirkan mereka semua.
Carleen terlihat gelisah lagi.
Apa pun itu, kamu harus tetap maju.]],
  str_mission_desc_4004060_long = [[
Shelt bergabung dengan saudarinya untuk bertarung bersama, tetapi masih ada ketimpangan.
Asap menyembunyikan Eclipsite bersaudari yang membuntuti ke 
kawasan perumahan Lumo Noble di Uptown!
Peringatan! Semua Guardian, kembali untuk bertahan sekarang juga!]],
  str_mission_desc_4004085_long = [[
Di Lumopolis Archive, Gertzurde mulai mengurai kode Think Tank Module yang terenskripsi.
Shelt bilang akan memancing musuh ke daerah Uptown dan mengulur waktu untuknya.
Carleen sadar hal tersebut akan menjadi usaha bunuh diri jika mereka melarikan diri ke Uptown;
Jadi dia meminta Raphael untuk melakukan pencarian di arah sebaliknya sementara dia melacak Eclipsite bersaudara.]],
  str_mission_desc_4004100_long = [[
Sementara itu, Raphael tidak berhasil menemukan pria misterius tersebut.
Alih-alih, dia malah bertemu Gertzurde, sang kapten skuadron, yang baru menyelesaikan misinya.
Dia memegang sebuah kotak yang ditutupi kain. Apa gerangan isinya?...]],
  str_mission_desc_4004110_long = "Mengikuti jejak darah, kamu sampai di sebuah tempat dekat Uptown. Eclipsite bersaudara tak punya jalan kembali.\nMereka dengan putus asa meminta bantuan kepada pria misterius itu hanya untuk mendengar bahwa—\nmereka hanya punya pilihan antara mengalahkan musuh dan selamat.",
  str_mission_desc_4004120_long = [[
"Aku akan berubah menjadi dandelion... dan terbang..."
Kata-kata dan kekuatan pria misterius itu mengubah dua bersaudara ini menjadi monster aneh.
Kekuatan seperti itu adalah alat yang kuat tetapi bukan alat penyiksaan yang manusiawi.
Kedua bersaudara yang sudah lama menderita tersebut akhirnya menjadi abu. Krisis mengganggu akhirnya selesai.
Misi Gertzurde tuntas. Sampai sejauh ini, Schummer berhasil mendapatkan Think Tank Module lengkap...]],
  str_mission_desc_4005015_long = [[
Illumina Legion Commander tidak boleh meninggalkan pos mereka, dan tidak bisa memberimu bantuan.
Kamu harus melacak Schummer dan menemukan Autonomous Growth Unit sendiri.
Philyshy, Intel Chief, mendapat petunjuk...
Sementara itu, Carleen ingin ikut dalam perintah khusus dari Lumopolis;
dia ingin mengejar Schummer bersamamu.]],
  str_mission_desc_4005010_long = [[
Jumlah Colossus yang gugur menunjukkan jumlah Caelestite yang berkorban.
Kini, kamu akhirnya tiba di relic Caelestite Tanpa Nama 13, sayangnya kamu malah mendapati dirimu di reruntuhan.
Direktur Riset Illumina, Gronru, pernah melakukan suatu penelitian di sini.
Memang benar bahwa Autonomous Growth Unit telah jatuh di tangan Colossus!
Kamu butuh kekuatan Caelestite bila ingin merebutnya dari Colossus.]],
  str_mission_desc_4005020_long = [[
Bagian dalam Colossus yang jatuh telah rusak parah, jadi jalan menuju Autonomous Growth Unit bergelombang dan bergolak.
Guncangan yang tak biasa menandai kedatangan Schummer.
Dia melepaskan kekuatan tanpa menahan diri dan mengolok-olok para pecundang lemah dan rendahan itu.]],
  str_mission_desc_4005060_long = [[
Pikiran orang mati adalah puisi dan juga syair, terjalin dalam kehampaan dan tersebar melintasi ruang dan waktu.
Modul kedua adalah hadiah terakhir yang mereka berikan kepadamu. Sekarang, Colossus mulai bersinar lagi dari dormansi.
Meski begitu, Schummer datang dari atas.
Untuk melindungi modul yang kamu peroleh, Gronru memanggil singgasana untuk melindungi kepergianmu.]],
  str_mission_desc_4005070_long = [[
Terminal berbunyi. 
Ternyata pesan dari Gronru, memerintahkan kalian semua mundur dengan cepat, tetapi Schummer menyela pembicaraannya.
"Kembalilah ke Colossus yang terbengkalai dalam 30 menit dan serahkan modulnya kepadaku, atau anggap Gronru tiada."
Abaikan atau selamatkan Gronru?]],
  str_mission_desc_4005090_long = [[
Tepat 5 menit sebelum tenggat.
Soroz tidak pergi atau mendarat. Keputusanmu sudah bulat.
Sementara itu, Gronru tidak hanya menunggu ajalnya. Dia lebih kuat dari yang bisa dibayangkan.]],
  str_mission_desc_4005120_long = [[
Bahkan untuk Caelestite, menggenggam kekuatan Eclipsite benar-benar membuat seseorang menjadi begitu kuat?
Schummer memenangkan dengan mudah. Tapi di luar dugaan kami, dia menepati janji yang membosankan itu. Tapi dia juga berkata, bahwa menyelamatkan hidup adalah belas kasihan dan kasih sayang. Pertempuran sampai ajal menjemput menantimu di putaran berikutnya.]],
  str_mission_desc_4006015_long = [[
Kamu harus menemukan Flame Control Module sekarang juga meski jika tidak mendapatkan banyak dukungan dari Illumina dan Lumopolis;
kamu memutuskan untuk pergi ke Whispering Corridor yang jauh itu sendirian
Whispering Corridor seperti labirin yang rumit, dan saat dirimu sedang resah, Shadowlord, Ruler of Umbraton, akan mengirimimu pendamping yang kompeten,
Ms. Sheol, yang akan memandumu menjelajahi labirin ini...]],
  str_mission_desc_4006010_long = "Operasi perburuan berjalan lancar meski kamu hanya dibantu Ms. Sheol dari kejauhan.\nJejak sepatu bot tentara membekas di antara jejak kaki Eclipsite—\nItu pasti Gertzurde, si pengkhianat yang dulu dianggap sebagai pahlawan Lumopolis.\nDia digiring untuk percaya kebohongan kematian Shelt, sehingga kebencian tumbuh di hatinya...",
  str_mission_desc_4006050_long = "Kamu sepertinya berhasil menemukan jalan yang tepat menuju Flame Control Module, tetapi kamu tidak boleh lengah. Gertzurde sepertinya bersembunyi di depan. Akankah ini menjadi pertempuran terakhirmu dengannya?",
  str_mission_desc_4006060_long = [[
Gertzurde, yang bertekad untuk membalas dendamnya kepadamu, kalah meski mendapatkan kekuatan kegelapan.
Dia akhirnya sadar bahwa apa yang disebut kebenaran adalah kebohongan yang dibuat oleh Schummer dan pria misterius untuk mengendalikannya.
Sayangnya, ini sudah terlambat. Dandelion sudah terbang bersama angin...
Gertzurde sangat sedih sehingga dia memutuskan untuk membawamu ke tempat Schummer berada.]],
  str_mission_desc_4006085_long = "Belasan tahun yang lalu, pascakrisis Darkover berakhir, Gertzurde dianugerahi gelar kebangsawanan. Dia tidak merasa bahagia dalam pernikahannya dengan seorang putri bangsawan, sehingga awal dongengnya tidak punya akhir yang bahagia, sampai dia bertemu Shelt, meskipun itu adalah pilihan yang salah.",
  str_mission_desc_4006070_long = [[
Eclipse tahu tentang pengkhianatan yang Gertzurde lakukan.
Dengan bantuan Gertzurde, Flame Control Module sudah ada di ujung jarimu.
Teman lamamu, Nozard, yang menjadi kuat setelah diubah oleh pria misterius itu sudah menantikan dirimu.]],
  str_mission_desc_4006110_long = [[
Kamu bisa merasakan bahwa Schummer sedang bersantai menantimu di suatu tempat.
Kamu sudah mengetahui tentang pengidentifikasi modul dari Gertzurde, tetapi ini berarti Schummer mungkin juga mengetahuinya!]],
  str_mission_desc_4006120_long = [[
Charon yang mengarungi Other End sendirian membuat Schummer percaya bahwa itu adalah bala bantuan Illumina.
Enggan mengambil risiko, pria misterius dan Schumer pergi, meninggalkan tubuh Gertzurde.
Carleen membakar tubuhnya, yang kemudian tertiup angin bersama Shelt...
Sementara itu, Lumopolis menghadapi krisis yang lebih besar...]],
  str_mission_desc_4007015_long = [[
Colossus hitam Schummer tiba di atas langit Lumopolis.
Tanpa perlindungan perisai, Lower Lumopolis berada dalam bahaya besar. Untungnya, Illumina Legion Commander terdekat datang untuk membantu.
Schummer pasti menerima balasan perbuatannya, setelah ancaman langsung ini disingkirkan!]],
  str_mission_desc_4007010_long = [[
Semakin banyak Eclipsite berkumpul di Lower Lumopolis.
Mengingat kurangnya dukungan dari para prajurit, semua orang hanya bisa mengambil tindakan secara terpisah.
Namun, kamu kembali diseret ke dalam pertempuran tanpa akhir.]],
  str_mission_desc_4007050_long = [[
Berkat taktikmu, operasi penyelamatan dan penyingkiran di Lower Lumopolis berhasil dituntaskan dengan cepat.
Koneksimu dengan Soroz sangatlah lemah, tetapi sepertinya aman.
Saat semua orang merasa lega, Carleen menyadari bahwa Uptown tengah diserang!]],
  str_mission_desc_4007060_long = "Colossus hitam adalah ancaman nyata bagi seluruh pulau melayang ini,\ntetapi semua orang berhasil bergegas ke Uptown tepat waktu dan menjatuhkan Mara Sol.\nPertempuran berakhir dengan kesombongan Schummer. Namun, saat itu, kamu mendengar teriakan bantuan—\nApakah Colossus sedang diserang?!",
  str_mission_desc_4007085_long = [[
Kamu mencoba segalanya untuk terhubung dengan Soroz tetapi gagal.
Tidak ingin mendapatkan risiko yang terburuk, prioritas utama saat ini adalah untuk segera kembali membantu Soroz.
Tepat ketika semua orang kehabisan akal karena tidak ada kendaraan, 
Carleen menerbangkan pesawat rampasan mendekatimu bak melakukan penyelamatan.]],
  str_mission_desc_4007070_long = [[
Soroz berantakan pasca invasi Eclipsite.
Konsekuensi terburuk sudah diramalkan, tetapi kamu yakin Soroz masih hidup.
Temukan Soroz sebelum Schummer mengetahuinya!]],
  str_mission_desc_4007100_long = [[
Kamu akhirnya merasakan Soroz setelah pertempuran.
Tapi itu bukanlah teriakan lagi, melainkan pesan berulang.
Apa itu berarti... nasib buruk menimpa Soroz?]],
  str_mission_desc_4007110_long = "Keberadaan Soroz menghilang, \ndan rasa sakit yang berdenyut di hatimu adalah pengingat akan anomali.\nSayang, Schummer bilang Soroz sudah—",
  str_mission_desc_4007120_long = [[
Demi Soroz, kamu bertarung dengan Schummer yang semakin kuat!
Yang paling mengejutkan adalah munculnya Eclipsite level tinggi lainya, Forsakin, salah satu pendamping yang dulunya mengabdi kepada Illumina!
Kamu belum sempat merasa terkejut ketika Colossus hitam itu tiba-tiba diserang.
Vivian berencana untuk mengorbankan hidupnya agar kalian bisa lari.
Setelah tabrakan yang menimbulkan kehancuran besar, apa lagi yang akan kamu hadapi selanjutnya...?]],
  str_mission_desc_4008015_long = [[
Sebuah tangis membangunkanmu dari mimpi yang aneh.
Kamu di dalam Aviduz bersama Vice, yang tak pernah ragu untuk menyelamatkanmu.
Kamu harus mencari cara untuk kabur...]],
  str_mission_desc_4008020_long = [[
"Tak boleh ada yang tertinggal."
Dengan pemikiran ini, kamu memutuskan untuk menyelamatkan Chief Vivian terlebih dahulu.
Sementara itu, sosok misterius terus memandumu...]],
  str_mission_desc_4008030_long = [[
Saat kamu bergerak, tubuhmu terasa aneh.
Meski begitu, tidak ada waktu untuk memeriksanya, dan kamu harus menemukan Vivian secepatnya.
Sementara itu, kamu yakin Carleen juga pasti mengerahkan segala kemampuannya untuk bertarung...]],
  str_mission_desc_4008060_long = [[
Ketidaknormalan dalam tubuhmu tak bisa diabaikan. Ada sesuatu yang akan terjadi,
karena saat dalam pertempuran pun, bahkan Eclipsites tak mengindahkanmu...
Apa-apaan bayangan ini?]],
  str_mission_desc_4008070_long = [[
Ketika Curie menerobos, kamu akhirnya mencapai tempat Chief Vivian ditahan,
dan tempat Solfall, musuh tangguh, menantimu...
Setelah mengalahkannya, sosok misterius tersebut menunjukkan wujud aslinya dan membantumu menyingkirkan benda asing yang dikenal sebagai "seed."]],
  str_mission_desc_4008085_long = "Di Lumopolis, Carleen gagal mendapatkan bantuan dari Lord.\nMeskipun begitu, ini tidak menggoyahkan tekadnya untuk menggunakan senjata pemungkas—\nDi ruang kendali, Carleen telah membulatkan tekad untuk mengaktifkan Damocles sendiri!",
  str_mission_desc_4008090_long = "Meskipun Chief Vivian berhasil diselamatkan, tidak baik bila harus keluar sekarang.\nInilah titik balik pertempuran, dan kelompok tersebut telah menjadi kekuatan kunci untuk melumpuhkan musuh dari dalam.\nKamu tidak boleh pergi—kamu harus berhenti bertahan dan mulai menyerang!",
  str_mission_desc_4008100_long = "Pertempuran semakin memanas, dan Schummer akhirnya menyadari tindakanmu.\nTampaknya pertempuran sengit ini sudah ditakdirkan terjadi di wilayah terpenting di Black Colossus—jembatan!\nSementara tu, Damocles juga mulai meracik gempuran terakhirnya...",
  str_mission_desc_4008130_long = "Sambil berdiri di depan Lumopolis yang sudah lama ia dambakan, apa yang dipikirkan Schummer sekarang?\nAkankah pikirannya dipenuhi kenangan masa lalu, atau mungkin penyesalan?\nKamu harus meneruskan ini—sumber dari segala kekacauan ini sudah ada di depan!",
  str_mission_desc_4008140_long = "Pertempuran puncak di jembatan. Para Eclipsite yang ada di hadapanmu menghilang dengan cepat.\nKarena tak tahu menahu tentang Damocles, Schummer segera merasakan kekuatan penghancurnya—\nCarleen menginisiasi serangan meriam cahaya, dan berkat bantuanmu, dia berhasil menembus Aviduz.\nBadai hitam akhirnya jatuh dalam kekalahan...",
  str_mission_desc_4008155_long = "Sementara, ketika pertempuran mereda—\nSejumlah figur penting yang diangkat untuk menyetir arah dunia muncul dari balik tirai dan mengambil alih panggung tengah.\nPusaran takdir yang membayangi mulai terbentuk. Bagaimana caramu mengarahkan takdir akhirmu?",
  str_mission_desc_4009015_long = "Setelah insiden Damocles, Carleen mendapat hukuman sementara, dan kamu mendapat tugas penting untuk mencari tahu penyebab insiden itu.\n\"Tubuh\" Schummer harus ditemukan, dan masalah ini harus diselesaikan jika kamu ingin memperbaiki Soroz.\nDan secara kebetulan, Aviduz jatuh di tempat yang familier tetapi aneh itu—Eraveil.",
  str_mission_desc_4009020_long = [[
Eraveil yang menantimu sangat berbeda dengan yang kamu saksikan dalam penglihatanmu.
Tempat itu tandus, hancur, terkontaminasi dengan energi aneh, dan dibanjiri oleh kawanan Eclipsite.]],
  str_mission_desc_4009030_long = [[
Setelah Colossus jatuh di Eraveil, kamu bergabung dengan anggota Rediesel Wrench dalam perjalanan menemukannya.
Sinsa dan Bopper bermaksud menyelamatkan beberapa material dari puing-puing, tetapi justru terpisah dari kelompok mereka.]],
  str_mission_desc_4009040_long = [[
Kamu dan Sinsa tiba-tiba bertemu lagi, tetapi dia sepertinya tidak tahu persis di mana dia berada.
Namun, tak ada waktu untuk mengobrol. Tugas pertama adalah mulai mencari Aviduz...]],
  str_mission_desc_4009050_long = [[
Meskipun penjelajahan menjadi lebih lancar berkat bantuan Sinsa, hawa menjadi lebih dingin.
Satu-satunya penjelasan adalah bahwa tempat ini kini menjadi sarang Eclipsite...]],
  str_mission_desc_4009070_long = [[
Kamu menemukan sebuah lencana yang membuktikan bahwa salah satu Eclipsite tersebut dulunya adalah seorang Aurorian.
Sepertinya musuh yang sudah berubah wujud itu, yang ada di depanmu, dulunya sama seperti teman-teman Aurorian-mu.
Kamu harus mengakhiri penderitaannya.]],
  str_mission_desc_4009085_long = [[
Setelah pulih dari lukanya yang menyedihkan di dalam cangkang penyembuhannya, Schummer memimpikan dirinya di masa silam.
Schummer dari masa lalu menceritakan tekad dan keinginannya dengan sungguh-sungguh dan menunggu kelahirannya kembali.]],
  str_mission_desc_4009090_long = [[
Kamu merasakan kesedihan dan keputusasaan yang terpancar dari dalam Eraveil.
Mungkinkah ini ilusi? Atau justru kenyataan? Apakah Aviduz juga menangis kesakitan?]],
  str_mission_desc_4009130_long = [[
Setelah mengalahkan Eclipsite di Eraveil, akhirnya kamu sudah dekat dengan tempat jatuhnya Aviduz.
Namun, para anggota True Order yang beroperasi secara sembunyi-sembunyi sepertinya juga mempunyai urusan di sini dan mengumpulkan sesuatu dalam bayangan...]],
  str_mission_desc_4009140_long = [[
Saat bertemu lagi dengan Forsakin, sepertinya dia agak terkejut karena kamu belum "berubah".
Dia melarikan diri sebelum kamu sempat membalas dendam.
Akan tetapi, sebelum kabur dia tidak sengaja membocorkan petunjuk penting yang menyatakan bahwa Schummer masih hidup.]],
  str_mission_desc_4010015_long = [[
Sementara itu, di Lumopolis Medical Center...
Philyshy mengunjungi Vivian dan memberitahunya bahwa kamu mengejar Forsakin.
Dengan singkat mereka berdua juga membahas hubungan antara Forsakin dan Grand Marshal...]],
  str_mission_desc_4010020_long = [[
Untuk melanjutkan pengejaran atas Forsakin dan pencarian Schummer, kamu memasuki Aviduz.
Meskipun sudah sekian lama Aviduz jatuh, puing-puingnya masih memancarkan kekuatan Darkflow yang luar biasa.
Yang lebih membingungkan lagi, Eclipsite di dalamnya berlarian dengan tergesa-gesa, seakan-akan sesuatu yang mengerikan telah bangkit di dekatnya...]],
  str_mission_desc_4010030_long = [[
Masih memulihkan diri dari luka-lukanya, Schummer terbangun lebih awal dan memakan Eclipsite untuk meregenerasi energi!
Meskipun tidak bisa memahami penolakannya ke dalam kerusakan yang jauh lebih dalam, kamu harus melanjutkan dan menemukan musuh bebuyutanmu!]],
  str_mission_desc_4010070_long = [[
Your enemy collapsed in death's arms once again.
Ketidakpedulian Forsakin yang kejam dan tidak bermoral membuatmu sangat marah. Kamu harus menemukannya dan Schummer!
Sementara itu, dalam pengejaranmu, informasi lebih lanjut tentang masa lalu Schummer mulai terkuak...]],
  str_mission_desc_4010085_long = "Pada hari itu tujuh belas tahun lalu, Schummer menjadi pertanda kehancuran Eraveil.\nDia memulai kekacauan atas nama Eclipse. Beberapa terpaksa menerimanya, sedangkan yang lain melawannya sampai titik darah penghabisan.\nNamun, pada akhirnya bangsa Caelestite binasa. Dia menggunakan darah segar mereka untuk mewujudkan tujuannya sejak lama—evolusi kegelapannya.",
  str_mission_desc_4010090_long = [[
Setelah melihat kilasan masa lalu Schummer, kamu mengetahui bahwa mimpimu akan Eraveil mencerminkan tragedi atas ingatan masa lalu tersebut.
Keinginan untuk membalas dendam sudah cukup lama. Sudah saatnya menemukan Schummer dan mengakhiri semuanya.]],
  str_mission_desc_4010130_long = "Akhirnya Forsakin mendorong Schummer melewati ambang batas, memaksanya untuk meningkatkan kekuatannya secara besar-besaran—\nNamun, akibatnya dia menjadi kehilangan kendali. Dia muncul lagi di hadapanmu dalam kegilaan yang luar biasa.\nHanya satu dari kalian yang akan keluar dari pertempuran ini hidup-hidup.",
  str_mission_desc_4010140_long = "Kamu mengalahkan Schummer yang gila, tetapi kelihatannya ada aliran kekuatan yang tak ada habisnya dalam dirinya.\nForsakin menguras kekuatannya demi mendapatkan Seed.\nSchummer, yang tujuan hidupnya hanyalah untuk keadilan dan kelahiran kembali, akhirnya tewas di tengah gerombolan Eclipsite—\nPersis seperti kaumnya sekian tahun yang lalu.",
  str_mission_desc_4010155_long = [[
Berkat bantuan Rediesel Wrench, semuanya berhasil meloloskan diri dari Aviduz dengan selamat dan meninggalkan Eraveil.
Kamu juga berhasil menghubungkan Think Tank Module yang didapat dari Schummer dengan Soroz, dan sejauh ini perbaikannya terlihat menjanjikan.
Sekarang, mau tak mau kamu jadi bertanya-tanya ke mana gerangan petualangan berikutnya akan membawamu...]],
  str_mission_desc_4101015_long = "Soroz kehilangan kestabilannya tanpa Echo Template. Jika masalah ini tak cepat diperbaiki, kerusakan mungkin terjadi. Kamu dan Vice memutuskan untuk singgah di Undercity tepat di tepi Land of Eternal Night berdasarkan petunjuk Think Tank Module.",
  str_mission_desc_4101020_long = "Setibanya di Undercity 80 tepat di tepi Land of Eternal Night, kamu menyadari bahwa Eclipsite telah menduduki tempat ini sejak ditinggalkan oleh Illumina. Darkflow yang pekat menyebabkan Luminatics tak dapat digunakan. Dalam situasi seperti ini, kamu memulai investigasi dengan sangat hati-hati.",
  str_mission_desc_4101030_long = "Kamu dan Vice merangsek ke dalam Undercity. Jejak peperangan terpampang jelas di mana-mana, tertutup debu tebal yang menumpuk selama bertahun-tahun. Di reruntuhan itu, kamu menemukan sejumlah modul Colossus rongsok…",
  str_mission_desc_4101040_long = "Komponen yang dapat dimanfaatkan untuk memperbaiki Echo Template Soroz terpasang di mesin yang terletak di ruang inti energi. Kamu mencoba melepaskannya secara paksa sehingga menyebabkan inti energi Undercity ini berhenti berfungsi. Tanpa pasokan daya, Undercity mulai runtuh dan High-Level Eclipsite mulai bermunculan.",
  str_mission_desc_4101055_long = "Kamu dan Vice menghadapi High-Level Eclipsite di tengah tekanan berat yang ditimbulkan oleh Darkflow sambil mencari kesempatan untuk melarikan diri. Namun, High-Level Eclipsite menghadang pelarianmu. Di saat genting ini, Reinhardt datang menyelamatkanmu. Kamu terkejut saat menyadari bahwa High-Level Eclipsite itu adalah kawan lama Reinhardt.",
  str_mission_desc_4101060_long = "Reinhardt memandumu ke rute pelarian lain menuju permukaan. Namun, semakin kamu melangkahkan kaki, semakin berat pula Darkflow yang menekan. Malam pun tiba. Mulai sekarang, pertarungan akan semakin sulit.",
  str_mission_desc_4101070_long = "Didera pertanyaan bertubi-tubi olehmu, Reinhardt mulai menceritakan kisah masa lalunya. Bersama rekan seperjuangannya, dia pernah terlibat dalam pertempuran sengit di Undercity 80. Dia berhasil membebaskan diri dari kepungan musuh untuk mencari bantuan. Namun, dia harus menelan fakta pahit bahwa Illumina meninggalkan mereka demi menyelamatkan penduduk lain.",
  str_mission_desc_4101080_long = "Di tengah gelap gulitanya malam, kamu berhasil mencapai permukaan tepat sebelum fajar menyingsing. Forsakin dan High-Level Eclipsite diam-diam menunggu kedatanganmu. Reinhardt meminta bantuanmu. Dia ingin mencoba membawa pulang rekan lamanya untuk yang terakhir kalinya.",
  str_mission_desc_4101090_long = "Forsakin membangkitkan kebencian High-Level Eclipsite yang terpendam dan mengubah wujudnya. Pertarungan yang mematikan pun tak dapat terhindarkan. Reinhardt mengalami cedera berat demi melindungimu. Di tengah situasi tanpa harapan ini, dia melancarkan perlawanan yang berani…",
  str_mission_desc_4101105_long = "Terancam oleh kepungan Eclipsite, kamu dan Vice membawa Reinhardt yang terluka parah kembali ke Soroz untuk mendapatkan pertolongan di Illumina. Di tengah perjalanan, Reinhardt teringat akan peristiwa masa lalu. Sejumlah perubahan penting tampaknya sedang terjadi di Undercity Illumina yang padat penduduk…",
  str_mission_desc_4201015_long = "Dengan mengikuti petunjuk yang berhasil diperoleh, kamu berangkat ke Eraveil untuk mencari Colossus Maintenance Base, berharap bisa menemukan cara untuk mengembalikan Soroz seperti semula. Namun, hal-hal tidak berjalan persis seperti yang direncanakan...",
  str_mission_desc_4201020_long = "Dalam perjalanan ke Eraveil, Soroz diserang oleh Eclipsite. Sesuatu yang sepertinya merupakan penyergapan terencana. Selama pertempuran, serangan Eclipsite menghancurkan panel kontrol Colossus, dan Soroz pun mulai jatuh...",
  str_mission_desc_4201040_long = "Kamu mendarat di suatu ruangan yang luas di dasar White Tower. Menurut data Soroz, ini adalah \"Tarmac\", jadi pangkalan yang kamu cari seharusnya tak jauh. Saatnya mengambil detektor logam dan mulai menjelajah.",
  str_mission_desc_4201050_long = "Saat kamu mulai melakukan pencarian, beberapa Eclipsite diam-diam mengikutimu di White Tower. Untuk melanjutkan pencarian itu, kamu meledakkan jalan masuk ke Tarmac dengan bantuan Barton sehingga mereka tak bisa mengikutimu lebih jauh.",
  str_mission_desc_4201060_long = "Dengan mengikuti jalan masuk yang kamu temukan, kamu memasuki pangkalan luas di bawah Eraveil. Kamu menemukan banyak jejak Caelestite yang pernah tinggal di sini sebelumnya, yang tak pernah kamu ketahui keberadaannya.",
  str_mission_desc_4201070_long = "Setelah terlibat dalam pertempuran sengit, kamu jatuh pingsan karena kekurangan oksigen. Secara kebetulan, kamu terhubung dengan AI yang mengontrol pangkalan itu. Berkat bantuannya, ventilasi dihidupkan dan kamu pun siuman. Dengan panduan AI itu, kamu terus menjelajahi pangkalan...",
  str_mission_desc_4201090_long = "Kamu tiba di ruang yang terbentang luas di pangkalan. Ada tanda-tanda bahwa area ini pernah dikenal sebagai Exiled Zone dan kamu menyadari bahwa orang-orang yang diasingkan di sini pada masa lalu adalah kaum Caelestite. Di sini, kamu menemukan Lance Rifle yang dulunya milik seorang Caelestite dan berhasil menggunakannya untuk mengalahkan Eclipsite.",
  str_mission_desc_4201100_long = "Karena dikejar oleh Eclipsite yang kuat, kamu tak punya pilihan selain menggunakan perangkat pertahanan pangkalan bawah tanah untuk menghadapinya. Sayangnya, perangkat ini tak hanya untuk menyerang Eclipsite, tapi juga berbahaya bagi Aurorian. Vice juga terluka dan tak sadarkan diri akibat kondisi aneh yang dikenal sebagai \"Hibernation\".",
  str_mission_desc_4201115_long = "Demi menemukan obat untuk Vice dan memperbaiki Soroz, kamu melanjutkan penjelajahan di inti pangkalan. Di sana, kamu menemukan mesin aneh—Circular System—yang hanya bisa digunakan olehmu, seorang Caelestite. Dari mesin ini, kamu melihat sekilas beberapa rahasia misterius.",
  str_mission_desc_4201120_long = "Di Circular System, kamu berhasil menemukan catatan tentang cara memulihkan Aurorian dari Hibernation. Tapi, karena batasan umur, kamu hanya bisa mengakses sebagian informasi saja. Kamu pun memutuskan untuk menjelajahi kedalaman agar menemukan lebih banyak petunjuk.",
  str_mission_desc_4201140_long = "Saat sistem pangkalan tiba-tiba mulai melakukan reboot, kamu kehilangan kendali atas pangkalan dan menjadi target serangannya. Guardian di pangkalan itu telah terbangun dari tidur nyenyak, dan kamu harus mengalahkan mereka untuk mendapatkan kembali kendali atas pangkalan.",
  str_mission_desc_4201155_long = "Seiring dengan selesainya proses reboot, kamu mendapatkan kembali kendali atas pangkalan berikut akses penuhnya. Di tengah gemuruh getaran, menara itu mulai naik, perlahan memperlihatkan bentuk aslinya. Ciptaan teknologi kuno di seluruh penjuru Astra mulai bergema aneh...",
  str_mission_desc_4202015_long = "Setelah mendapatkan akses administratif ke Obelisk of Return, kau mengetahui bahwa perangkat yang disebut \"Chord Link\" bisa digunakan untuk menyelamatkan Vice. Tapi, karena Obelisk of Return itu sudah rusak, tak ada informasi tentang perangkat tersebut di sistem sehingga kau harus pergi ke area tempat perangkat itu berada untuk menyelidiki lebih lanjut.",
  str_mission_desc_4202020_long = "Saat kau mencari Chord Link, Barton mengikuti jejak Forsakin ke menara. Tapi, dia justru tersesat di Obelisk of Return yang luas...",
  str_mission_desc_4202040_long = "Setelah Barton mengejarnya, Forsakin membatalkan rencananya untuk mengikutimu dan mencari cara lain. Kamu harus berpacu dengan waktu demi memecahkan Access Control Chord Zone sambil bertahan dari serangan Forsakin.",
  str_mission_desc_4202050_long = "Kamu melarikan diri ke Chord Zone untuk menghindari Forsakin, tapi tindakanmu untuk memecahkan Access Control justru memicu pertahanan Chord Zone. Dengan diaktifkannya semua perangkap di lorong, kamu dihadapkan dengan rintangan yang menantang. Tepat ketika situasi mencapai klimaks, kamu pun memicu ledakan perangkap, menghentikan Forsakin untuk sesaat sehingga kamu berhasil memasuki Chord Zone.",
  str_mission_desc_4202060_long = "Untuk melindungi Vice dan mengalahkan Forsakin, Barton, yang terluka parah, memutuskan untuk mengubah dirinya dengan Chord Link. Selama waktu ini, Forsakin memerintahkan Eclipsite untuk mendobrak gerbang. Kamu pun berhadapan dengan Forsakin demi mengulur waktu untuk Barton.",
  str_mission_desc_4202070_long = "Setelah Barton menyelesaikan sinkronisasi, dia mendapatkan kekuatan baru dan keluar dari Chord Link untuk bergabung denganmu dalam melawan Forsakin. Saat situasi berbalik, Forsakin melarikan diri dari kekacauan dan Barton pun mengejarnya...",
  str_mission_desc_4202085_long = "Keberhasilan Barton membuatmu yakin, dan kau pun memasukkan Vice ke Chord Link untuk menjalani sinkronisasi. Melalui pengamatan dari Obelisk of Return, kau melihat Eclipsite mengumpulkan pasukan besar di luar menara dan Aurorian dari segala sisi berjuang sekuat tenaga. Saat menyaksikan ini, kau memutuskan untuk mengusir Eclipsite ini dari Eraveil dengan tanganmu sendiri.",
  str_mission_desc_4202090_long = "Karena Vice belum juga siuman, kamu dan Carleen tak punya pilihan selain meninggalkannya di Chord Link untuk mengusir Forsakin dari menara. Saat ini, pemandangan di luar menara sangat mengerikan. Eclipsite dalam jumlah besar dan Aurorian bertarung dengan sengit. Seolah-olah waktu telah kembali ke hari ketika Eraveil diserang tujuh belas tahun yang lalu...",
  str_mission_desc_4202100_long = "Di tengah gempuran tanpa henti dari Eclipsite, semua orang bersikap tegar dan berusaha sekuat mungkin untuk bertahan. Kemudian, Eclipse mengeluarkan kartu truf mereka—meriam Darkflow. Senjata tak terduga ini langsung membuatmu kewalahan. Harapan akan kemenangan tampaknya memudar dengan cepat...",
  str_mission_desc_4202115_long = "Karena semua orang di luar Obelisk of Return tetap bertempur dengan sengit, demi membalik keadaan, Reinhardt menyarankan untuk meninggalkan beberapa orang sebagai pengalih perhatian, sementara kau dan dia menyergap Eclipsite. Demi melindungi Eraveil, kau memutuskan untuk bekerja sama dengan Reinhardt.",
  str_mission_desc_4202130_long = "Karena Reinhardt dan Forsakin masih bertempur dengan sengit, situasi pun belum berbalik. Setelah merasakan krisis yang akan segera terjadi, kau pun memutuskan untuk kembali ke Obelisk of Return dan mengakses Core Ring untuk mengaktifkan senjata pemungkas Obelisk of Return—Chord of the Law.",
  str_mission_desc_4202140_long = "Kamu menghadapi para Guardian sendirian demi mendapatkan akses ke Core Ring, tapi kamu tak bisa mengalahkan mereka. Tepat ketika kamu nyaris kalah, Vice, yang baru saja pulih dari Hibernation, tiba di sisimu dengan kekuatan barunya. Kalian bekerja sama untuk mengalahkan Guardian dan akhirnya mengaktifkan Chord of the Law.",
  str_mission_desc_4202155_long = "Berkat \"hadiah\" yang ditinggalkan Master Francis untukmu, kau bisa mengaktifkan Chord of the Law, menjauhkan semua Eclipsite dari Obelisk of Return dan mengakhiri pertempuran. Obelisk of Return, yang tak bisa diaktifkan lagi karena kekurangan energi, menjadi monumen sejarah, dan semua orang bertanya-tanya tentang apa yang akan terjadi padanya...",
  str_mission_desc_4203015_long = "Tubuh Vice tiba-tiba mulai memancarkan cahaya aneh, kemungkinan efek samping dari penggunaan Chord Link. Khawatir dengan situasinya, Anda menghubungi Vivian dengan harapan dia dapat mengidentifikasi sumber masalahnya.",
  str_mission_desc_4203020_long = "Karena mengkhawatirkan keselamatan Vice, Anda setuju untuk membantu tim peneliti dari Illumina menyelidiki fungsi baru Soroz. Selama penyelidikan, para peneliti menemukan sejumlah besar data pertempuran kuno; mereka sekarang ingin Anda mengakses data ini menggunakan Illumina's Battle Simulator dan melakukan penelitian lebih lanjut tentangnya.",
  str_mission_desc_4203030_long = "Anda melakukan sejumlah tes menggunakan Battle Simulator, perangkat canggih yang digunakan untuk membuat skenario pertempuran yang nyaris sempurna. Setelah melihat simulator beraksi, Reinhardt percaya bahwa dengan menghasilkan pertempuran yang lebih kompleks, perangkat ini bahkan dapat digunakan untuk tujuan pelatihan.",
  str_mission_desc_4203040_long = "Anda memasuki Battle Simulator sekali lagi, tetapi lingkungan di dalamnya telah diubah menjadi Zona Gelap. Dalam simulasi yang gelap dan bermusuhan ini, tujuan Anda adalah mengalahkan Eclipsites dan menerobos pengepungan mereka.",
  str_mission_desc_4203050_long = "Menggunakan medan untuk menambah keuntungan kecil, Anda akhirnya mengalahkan Eclipsites yang disimulasikan terakhir. Terpukul dan memar, Anda dan sekutu Anda muncul dari Simulator Pertempuran setelah kemenangan yang diperjuangkan dengan susah payah dan menemukan Reinhard berbicara kepada peneliti lain. Anda mendengar sebagian dari percakapan mereka dan menemukan bahwa Reinhard secara pribadi hidup melalui pertempuran yang baru saja Anda alami...",
  str_mission_desc_4203060_long = "Anda kembali ke simulator, dan lingkungan telah diubah secara drastis sekali lagi. Aurorian dalam simulasi menggunakan senjata yang belum pernah Anda lihat sebelumnya dan mati-matian menangkis gelombang demi gelombang Eclipsites yang haus darah. Saat mereka jatuh ke monster satu per satu, dunia virtual tampaknya tumbuh semakin tanpa harapan...",
  str_mission_desc_4203070_long = "Di dalam pertempuran simulasi, tragedi perang apokaliptik menyerang semua indra Anda. Tentara yang putus asa, Eclipsites yang mengamuk, dan monster iblis yang belum pernah Anda lihat mengelilingi Anda ... Tiba-tiba, terjadi kesalahan di simulator, dan tepat ketika Anda akan jatuh ke dalam serangan ganas Jormungand, Soroz memasukkan kesadarannya ke dalam pertempuran dan berhasil menarik Anda keluar. Ketika Anda mendapatkan kembali akal sehat Anda, Anda terkejut menyadari ...",
  str_mission_desc_4203085_long = "Dewan Sains, sebuah organisasi yang menyimpan rahasia Federasi Illumina yang paling dijaga dengan baik, telah secara pribadi mengundang Anda dan Reinhardt untuk bertemu dengan mereka. Apapun motifnya, merekalah yang paling bisa memahami kondisi Soroz saat ini. Saat Anda memasuki ruang konferensi, rasa tidak nyaman yang membayangi Anda. Tiba-tiba, Reinhardt dengan lembut meletakkan tangannya di bahu Anda, memecah ketegangan yang menindas yang menggantung di ruangan.",
  str_mission_desc_4203090_long = "Di akhir pertemuan, Anda dan Algol mencapai semacam kesepakatan. Atas permintaannya, Anda memulai Mind Link dengan Guardian One, mesin kuno milik Federasi Illumina. Melakukan hal itu akan menguntungkan kedua belah pihak: para peneliti Illumina akan memiliki kesempatan untuk mengamati interaksi Caelestite dengan perangkat kuno, dan Anda akan memiliki kesempatan untuk meminta bantuan Guardian One.",
  str_mission_desc_4203100_long = "Dalam proses membangun Mind Link dengan Guardian One, Anda menyadari bahwa meskipun sudah ada selama bertahun-tahun, kecerdasan buatan ini memiliki kepribadian seperti anak kecil; dengan demikian, itu hanya akan mempercayai mereka yang berinteraksi dengannya dengan kejujuran dan keadilan. Setelah merasakan kekhawatiran Anda terhadap Soroz, Guardian One segera memutuskan untuk membantu Anda menyelamatkan kesadaran Soroz.",
  str_mission_desc_4203110_long = "Guardian One membawa Anda ke medan perang simulasi tempat Soroz berada. Buntut dari bencana kuno dari ribuan tahun yang lalu terbentang di hadapan Anda, di mana Eclipsites masih berkeliaran di planet tak bernyawa. Mengetahui bahwa simulasi mendekati akhir, Anda harus mencari rekan yang Anda sayangi di antara reruntuhan dunia yang sekarat sebelum semuanya runtuh.",
  str_mission_desc_4203120_long = "Di reruntuhan dunia yang hancur, Anda akhirnya menemukan Soroz dan mengakses basis datanya. Akrab dengan hal-hal di sekitar Anda, namun tidak yakin dengan waktu atau tempat keberadaannya, kebodohan Anda akhirnya terpecahkan ketika Guardian One memberi tahu Anda bahwa ia telah menemukan sejumlah catatan kuno di dalam terminal. Di sini, Caelestites berada jauh dari rumah, mengembara ke arah tanpa tujuan...",
  str_mission_desc_4203130_long = "Guardian One memberi tahu Anda bahwa untuk memperbaiki Soroz, Anda harus terlebih dahulu memasukkan ingatannya dan memecahkan kesalahan dalam datanya. Dengan bantuan Guardian One, itu seharusnya menjadi tugas yang cukup sederhana. Saat memasuki ingatan Soroz, Anda melihat semakin banyak catatan terminal. Di dalamnya, Caelestite tampaknya semakin berkurang jumlahnya...",
  str_mission_desc_4203140_long = "Dengan bantuan Guardian One, Anda berhasil menghapus kesalahan di database Soroz. Dengan pikiran Anda masih pada catatan terminal, Anda memutuskan untuk mengaksesnya sekali lagi. Di dalam catatan, Anda menyaksikan keajaiban: di bawah asuhan Caelestites, Colossi lahir dan diberi perasaan. Setelah keajaiban singkat ini datanglah penantian yang lama, waktu yang begitu lama dan lancar sehingga membutuhkan setiap ons fokus Anda untuk mencapai akhir. Tiba-tiba, pemandangan yang akrab terbentang di hadapan Anda: Eraveil.",
  str_mission_desc_4203155_long = "Setelah keluar dari dunia virtual, Anda kembali ke ruang konferensi sekali lagi. Dewan Sains telah mulai mendiskusikan peristiwa yang baru saja mereka saksikan. Mereka percaya bahwa Soroz beroperasi sekali lagi, tetapi menyimpulkan bahwa perasaan Colossus tidak lebih dari akibat kecelakaan. Untuk benar-benar memulihkan kesadaran Soroz, Anda harus melakukan perjalanan ke tempat yang lebih jauh...",
  str_mission_desc_4204015_long = "Dipercayakan dengan Cyborg Tempur Fragile Dewan Sains, tugas Anda selanjutnya adalah melakukan kontak dengan pasukan Illumina yang ditempatkan di kota Twilight. Di sana, Anda harus menukar droid dengan sumber daya yang diperlukan untuk memulihkan kesadaran Soroz. Anda belum pernah mendengar tentang kota ini, yang terletak di garis depan Illumina; sangat mengejutkan Anda, Anda menemukan Carleen di sana pada tugas luar.",
  str_mission_desc_4204020_long = "Kota Twilight, yang terletak di dekat Reruntuhan Aurora dan berbatasan dengan zona Malam Abadi, adalah tempat berkumpulnya berbagai faksi militer. Ksatria Lumo yang ditempatkan di sini telah melakukan kontak dengan Carleen; tampaknya Beretta dan Yingel memiliki dua pemahaman yang sangat berbeda tentang tempat terpencil dan terpencil ini. Saat Eclipsites mulai menyerang, benda rapuh di tangan Anda mulai mengeluarkan suara aneh...",
  str_mission_desc_4204030_long = "Suara aneh membangunkanmu dari mimpimu, dan Soroz hampir \"dihapus\" oleh Sean. Ternyata, Sean bergegas dari Twilight setelah menerima pesan tentang kedatanganmu beberapa waktu lalu. Rencananya adalah untuk menyambut Anda sambil melakukan pekerjaan \"penghapusan\" seperti biasa, termasuk membersihkan Eclipsites dari area sekitar Twilight, serta penyerbu mencurigakan lainnya. Untuk petugas akar rumput seperti Sean, ini hanyalah praktik umum.",
  str_mission_desc_4204040_long = "Kapan Axelia, Yingel, dan Sean saling menyapa, Anda menyadari bahwa ketiganya memiliki sejarah yang sama. Mereka menjelaskan bahwa mereka adalah \"lulusan\" dari Program Phospherus, sebuah program yang dipelopori oleh Dewan Sains untuk tujuan mengasuh anak-anak menjadi tentara super. Meskipun mereka bertiga telah tumbuh banyak sejak saat itu, mereka masih saling menggoda dan tertawa seperti yang mereka lakukan saat masih anak-anak.",
  str_mission_desc_4204050_long = "Terlepas dari konflik biadab seputar Twilight, penduduknya lebih peduli untuk berlindung dari bencana alam yang akan segera terjadi. Aurora di atas kepala mengancam akan lepas kendali, dan semua orang mati-matian mencari perlindungan untuk mengatasi badai energi yang akan datang. Eclipsites memanfaatkan kepanikan yang meluas dan mulai menyerang tanpa pandang bulu. Saat Anda memutuskan untuk memasuki pertempuran dan menyelamatkan penduduk kota, Anda menemukan bahwa bala bantuan telah tiba dalam bentuk resimen tentara Lumopolis: Ironthorn Knights.",
  str_mission_desc_4204060_long = "Dalam menghadapi peluang yang tampaknya tidak dapat diatasi, para Ksatria Ironthorn dengan mudah mematahkan barisan Eclipsites sebelum menyerang mereka. Setelah melihat kehebatan tempur Leo yang luar biasa beraksi, Anda memutuskan untuk membantu para ksatria menangkis Eclipsites yang tersisa. Namun, saat pasang surut tampaknya menguntungkan Anda, ancaman baru dan bahkan lebih ganas muncul ...",
  str_mission_desc_4204070_long = "Gelombang baru Eclipsites memasuki medan perang, dan Ksatria Lumo tidak mampu menangkis serangan mereka sekaligus melindungi warga kota. Anda melepaskan diri dari garis depan untuk mempertahankan mereka, tetapi Eclipsites tidak henti-hentinya menyerang. Saat Anda mencapai batas Anda, seorang gadis muda tiba-tiba muncul di tengah pertempuran; dengan cahaya suci yang menyilaukan, dia langsung menghalau setiap Eclipsite di sekitarnya. Dengan keamanan warga kota, Anda bergabung kembali dalam pertarungan tanpa ragu dan akhirnya mengklaim kemenangan. Setelah itu, gadis misterius bernama Joselyne mengundang Anda untuk makan malam bersamanya di Twilight",
  str_mission_desc_4204085_long = "Joselyne membawa Anda ke sebuah restoran di Twilight dan memberi tahu Anda lebih banyak tentang kota: sejarahnya, masalahnya, dan yang paling penting, hubungannya dengan Colossus yang hilang dan kuno. Setelah selesai makan, Anda kembali ke Peneliti Illumina, yang membantu Anda memulihkan kesadaran Soroz sepenuhnya, meski hanya sementara. Pada saat-saat singkat itu, Soroz mengarahkan Anda ke lokasi tertentu: sebuah Undercity jauh di dalam Zona Gelap, tempat Colossus kuno tidak aktif...",
  str_mission_desc_4204090_long = "Anda memutuskan untuk melakukan perjalanan ke lokasi yang disebutkan Soroz dan mendapat dukungan dari Illumina dan Lumopolis, serta Joselyne yang baru dikenal. Setelah melihat kekuatan mereka yang mengesankan di medan perang, ancaman Eclipsites tampaknya jauh lebih tidak menakutkan dari sebelumnya.",
  str_mission_desc_4204115_long = "Anda dan sekutu Anda masuk lebih dalam ke reruntuhan. Waspada terhadap banyaknya Eclipsites yang berkeliaran di area tersebut, rombongan Anda melanjutkan dengan sangat hati-hati. Namun, saat ini, Sean memutuskan untuk menantang Axelia dalam adu kekuatan: siapa pun yang paling banyak mengalahkan Eclipsites adalah pemenangnya dan yang lebih kuat dari keduanya.",
  str_mission_desc_4204120_long = "Anda akhirnya tiba di Bridge of the Colossus, dan mulai mencari modul yang diperlukan. Namun, setelah menemukannya, Anda menemukan bahwa modul tersebut telah lama menyatu dengan Colossus; menghapusnya dengan paksa hanya akan menyebabkan lebih banyak kerusakan. Axelia kemudian masuk dan memberi Anda perangkat yang dapat menyalin data modul, tetapi mengatakan bahwa itu akan memakan waktu...",
  str_mission_desc_4204130_long = "Setelah menangkis Eclipsites yang menyerang, perangkat Axelia akhirnya selesai menyalin data modul. Saat rombongan Anda memutuskan untuk mengungsi, Colossus mulai bergemuruh dengan keras; apakah akan lepas kendali? Untuk menenangkan Colossus dan melindungi permukiman di dekat reruntuhan, Anda memutuskan untuk memulai Mind Link dengan Colossus...",
  str_mission_desc_4204140_long = "Tampaknya gemuruh itu bukan disebabkan oleh Colossus... Jadi apa yang menyebabkannya? Setelah membuat Mind Link dengan Colossus, Anda menemukan bahwa sejumlah besar Eclipsite telah berkumpul di luarnya; dalam barisan mereka, Anda merasakan kehadiran entitas yang sangat kuat...",
  str_mission_desc_4204155_long = "Anda kembali ke Twilight dengan Axelia dan yang lainnya di belakangnya dan mengucapkan selamat tinggal. Dengan data berharga Anda akhirnya di tangan, Anda melakukan perjalanan kembali ke Illumina. Hanya waktu yang akan menentukan apakah data ini benar-benar membantu memulihkan Soroz; yang bisa Anda lakukan hanyalah menunggu. Pada saat inilah Anda menerima undangan dari petinggi Illumina, permintaan untuk melakukan perjalanan ke Undercity yang tersembunyi di mana masih ada Chord Link lainnya...",
  str_mission_desc_4205015_long = [[
Memegang Vice sandera, Forsakin memaksa Anda untuk pergi bersamanya, tampaknya setelah Chord Link diam-diam ditemukan oleh Illumina, dengan tujuan melengkapi data eksperimen melalui Vice.
Di sisi lain, pertempuran di Twilight semakin intensif Leo mengirimkan sinyal marabahaya ke Lumopolis dan Illumina.]],
  str_mission_desc_4205020_long = "Untuk menyelesaikan percobaan, Forsakin memaksa Anda untuk melawan tentara Illumina dan menunda mereka. Hanya berharap dia menepati janjinya untuk tidak membunuh siapa pun.",
  str_mission_desc_4205030_long = "Anda telah tiba di tempat tujuan, di mana Forsakin, yang akrab dengan lingkungan sekitar, menyebut Institut X yang ia bangun! Sebelum Anda dapat merenungkan lebih jauh, dia ingin Vice untuk memulai Tautan Chord! Apa yang akan terjadi?",
  str_mission_desc_4205040_long = "Forsakin tidak senang dengan hasil operasi Chord Link. Anda dan Vice cobalah untuk menyergapnya, hanya untuk dia kemudian memanggil gerombolan Eclipsites untuk melawanmu.",
  str_mission_desc_4205041_long = "—",
  str_mission_desc_4205050_long = [[
Anda bukan tandingan Forsakin dan berjuang tanpa hasil. Helios muncul di sebelah Forsakin dan mengisolasi Anda dari Vice, memaksa Anda berdua untuk patuh.
Sementara itu, Ulysses menelepon Yingel untuk pertemuan rahasia dan menugaskannya dengan misi khusus.]],
  str_mission_desc_4205065_long = [[
Di Senja yang terkepung, Leo tidak menerima bantuan tetapi undangan untuk Latihan Militer Gabungan, yang dia ambil sebagai kesempatan untuk mengingatkan dunia akan ancaman dari Zona Gelap.
Sementara itu, Illumina dan Lumopolis juga mulai mempersiapkan latihan, seolah dalang di baliknya bersumpah untuk melihatnya sampai akhir...]],
  str_mission_desc_4205070_long = [[
Setelah Forsakin memisahkan Anda dan Vice, Anda tidak memiliki sarana untuk menghubunginya selain komunikator. Anda terus berjalan saat Forsakin mulai menggali arsip untuk info tentang Program Phospherus.
Sementara itu, Yingel bertemu dengan Petugas Intelijen Anatoli dengan perintah rahasia, sepertinya tujuannya adalah Institut X juga.]],
  str_mission_desc_4205080_long = "Untuk menemukan kamu yang hilang dan Vice, serta mengungkap apa yang sebenarnya ada di balik senam bersama, Carleen tiba di Illumina untuk diajak bicara Gronru, yang mengarahkannya ke Institut X, tempat dia bertemu Yingel secara kebetulan dan mencari tahu tentang krisis di sini.",
  str_mission_desc_4205090_long = "Forsakin mencoba mendapatkan lebih banyak info tentang Program Fosfer tetapi secara tidak sengaja memicu pertahanan. Setelah mengalahkan mereka, dia mengubah kata kunci dan berhasil mengakses file.",
  str_mission_desc_4205100_long = "Anda kehilangan kontak dengan Vice ketika komunikator kehabisan tenaga, tetapi tidak sebelum memberi Yingel dan waktu lainnya untuk mencari tahu lokasi persis Vice.\nNamun, ketika Yingel semakin dekat, dia menyadari musuh yang kuat sedang menjaga Vice—Helios.",
  str_mission_desc_4205101_long = "—",
  str_mission_desc_4205110_long = [[
Yingel dan Helios terkunci dalam pertarungan sengit. Dia juga menyadari Forsakin kemungkinan besar akan merasakan pertempuran tersebut.
Sementara itu, Carleen mencapai Anda. Dia mencoba untuk mengalahkan Forsakin dan mengeluarkanmu dari sini, hanya untuk terperosok dalam perjuangan beratnya sendiri.
Pemandangan putus asa dari Helios yang bekerja sama dengan Forsakin meminta Yingel untuk dengan berani membakar Chord Link...]],
  str_mission_desc_4205120_long = "Apa yang disebut neraka ternyata hanyalah ilusi belaka Yingel, tetapi itu mengubah gelombang pertempuran dan memberikan keunggulan bagi pihak Anda. Yingel juga mencoba meyakinkan Forsakin itu Reinhardt tidak pernah meninggalkannya setelah kebakaran lab dan apa yang disebut balas dendamnya salah arah sejak awal.",
  str_mission_desc_4205130_long = [[
Menolak untuk menyerah, Forsakin memutus aliran listrik ke lab dan menyegel pintunya, mengulur waktu untuk dirinya sendiri dan Chord Link untuk lebih meningkatkan Helios.
Sementara itu, motif Ulysses perlahan terungkap, karena dia sangat tertarik dengan hasil eksperimen Forsakin...]],
  str_mission_desc_4205140_long = [[
Terakhir, Forsakin menggabungkan tiga peningkatan berbeda pada Helios, mengubah penampilannya secara drastis. Setelah pertempuran berakhir, secara mengejutkan Helios mendapatkan kembali akal sehatnya, meskipun dengan ingatan yang agak terfragmentasi.
Sementara itu, Wrath Dan Reinhardt tiba untuk menghadapi Forsakin, tapi dia masih berhasil kabur.]],
  str_mission_desc_4205155_long = [[
Tidak ada yang bisa menemukan Forsakin di Institut X dan berspekulasi dia mungkin bersembunyi di dekat Gannon. Sementara itu, Latihan Militer Gabungan dimulai sesuai rencana di kota itu, saat perwakilan dari berbagai kekuatan berkumpul dan memperebutkan gelar tentara terbaik.
Tapi dalam bayang-bayang Gannon, Forsakin dan Helios mengintai...]],
  str_mission_desc_4206015_long = [[
Latihan dimulai, menarik tim Gannon dari Lumopolis, Illumina, dan Twilight, serta trio Anda dan regu misterius lainnya.
Vivian memberi tahu Anda tentang peraturan dan menunjukkan bahwa pemenang akan merasa terhormat untuk menantang Marsekal Agung.
Sementara itu, di sudut kota, Forsakin menunggu sesama anggota Eclipse untuk menyelamatkan dirinya dan Helios.]],
  str_mission_desc_4206020_long = "Yang pertama adalah Battle Simulator yang familiar bagi semua orang untuk menghidupkan kembali kampanye yang sulit dari masa lalu. Banyak yang menderita kekalahan melawan rintangan yang luar biasa, kecuali pasukan Leo dari Twilight, yang memperoleh kemenangan ajaib.",
  str_mission_desc_4206030_long = "Berikutnya adalah bagian ruang kelas, di mana seseorang dapat menukar kredit kursus berdasarkan nilai dan kinerja dengan persediaan. Jadi, di bawah pengawasan Wrath, semua orang mempelajari seni \"perkelahian\" ...",
  str_mission_desc_4206040_long = [[
Pelatihan yang seharusnya tidak berbahaya disabotase dan hampir berakhir dengan bencana. Tebak kompetisi antar regu tidak begitu bersahabat, lagipula.
Sementara itu, diberikan Leo dan kinerja Yingel yang luar biasa, Anda memutuskan untuk mengajukan sesi simulator tambahan, tetapi seseorang juga melakukannya...]],
  str_mission_desc_4206041_long = "—",
  str_mission_desc_4206050_long = [[
Untuk Eclipsites yang muncul entah dari mana di Gannon, Leo dan Zhao melampaui otoritas mereka untuk memerintahkan tentara Illumina untuk mencapai resolusi. Wrath tidak terlalu tertarik setelah mencari tahu, tetapi menghargai bakat Leo.
Dalam sebuah percakapan, Wrath juga mempelajari keputusasaan di Twilight dan menyadari bahwa atasan sepertinya menyensor berita...]],
  str_mission_desc_4206060_long = [[
Pelajaran bergerak maju ke pertempuran yang sebenarnya dalam Latihan Militer Gabungan. Di bawah saran Anda, semua orang mengalahkan semua musuh melalui aliansi sementara, membawa acara ke segmen terakhir: Tangkap Bendera.
Semua orang mulai menghabiskan kredit kursus yang diperoleh untuk perlengkapan dan alat peraga untuk mengantisipasi pertempuran besar untuk merebut bendera di Undercity.]],
  str_mission_desc_4206070_long = "Pergi ke Undercity untuk mencari bendera, Anda, Carleen, Dan Vice sedang menyusun strategi ketika pasukan misterius dari Umbraton itu berlari dengan sekelompok Eclipsites di...",
  str_mission_desc_4206080_long = [[
Anda akhirnya mengakhiri Eclipsites setelah pertempuran yang kacau, tetapi pasukan Umbraton yang memulai masalah menolak untuk memasuki Undercity bersama Anda, seolah-olah mereka memiliki misi sendiri.
Sedangkan dua regu terkuat, Tim Leo dan Tim Yingel, mulailah berkelahi satu sama lain di suatu tempat.]],
  str_mission_desc_4206090_long = "Dengan pasukan misterius yang tampaknya memanipulasi rute Anda, Anda bertemu dengan monster laba-laba yang berbahaya.\nSetelah pertempuran yang sulit, Anda bergegas ke tempat bendera hanya untuk menemukan pertarungan antar Tim Leo dan Tim Yingel berakhir, dengan pemenangnya adalah—Tim Yingel.",
  str_mission_desc_4206105_long = [[
Tim Leo sangat puas menjadi runner-up karena mereka melakukannya sebagai imbalan atas Illumina yang mengirim bala bantuan ke Twilight.
Sementara itu, Ulysses melanjutkan rencananya untuk mencapai tujuannya melalui aksi Forsakin di Gannon.
Memang, di tempat untuk melawan Grand Marshal, Yingel menerima berita tentang invasi Eclipsite di kota. Anda, Leo, dan yang lainnya memutuskan untuk membantunya dalam masalah ini.]],
  str_mission_desc_4206110_long = [[
Dalam pertarungan melawan Grand Marshal, Axelia menampilkan tingkat kekuatan yang tidak biasa dan keinginan mati. Reinhardt juga merasakan sesuatu yang aneh dalam pertandingan eksibisi.
Sementara itu, pengalihan Eclipsites membersihkan Forsakin dan Helios untuk melarikan diri dari Gannon melalui jalan rahasia.]],
  str_mission_desc_4206120_long = [[
The Eclipsites di Gannon tampaknya menarik perhatian Anda dengan sengaja, tetapi Anda juga tidak bisa berhenti begitu saja dan membiarkannya mengamuk. Sementara itu, Anda juga merasakan kehadiran Figerald the Wraith.
Di arena, pelanggaran hampir bunuh diri Axelia mulai memprihatinkan Reinhardt.]],
  str_mission_desc_4206121_long = "—",
  str_mission_desc_4206130_long = [[
Reinhardt mengakui hanya untuk berhenti Axelia dari serangan bunuh dirinya sendiri, tetapi itu juga termasuk dalam rencana Ulysses.
Anda, Leo, Yingel dan yang lainnya bergegas ke lokasi Wraith, tempat mainframe Guardian One disimpan!
Sementara itu, Forsakin dan Helios tiba di tempat pertemuan hanya untuk mengetahui bahwa Esien telah mengirim tentara ke sana. Mereka menyadari bahwa Eclipse telah menjebak mereka.]],
  str_mission_desc_4206140_long = [[
Diturunkan menjadi bidak pengorbanan belaka oleh Eclipse, Figerald benar-benar dikalahkan dan ditahan. Tapi Wraith tak dikenal lainnya telah mengambil inti Guardian One dan tidak ada yang bisa dilakukan siapa pun untuk mengatasinya.
Adapun Forsakin, dia lolos saat Helios tetap tinggal untuk menutupi pelariannya.
Kembali ke arena, Ulysses mengungkapkan bahwa Komite telah menemukan bukti Reinhardt menyembunyikan Forsakin di kediamannya, menahan Marsekal Agung di depan semua orang.]],
  str_mission_desc_4206155_long = [[
Dan di sinilah letaknya. Bahkan jika Anda menemukan Reinhardt dikeluarkan dari tugas pil yang sulit untuk ditelan, itu masih fakta.
Adapun Ulysses, dia sangat puas dengan mencegat hasil eksperimen Forsakin, tetapi Wraith memanfaatkan kesempatan untuk mencuri Penjaga Satu merusak operasi.
Apa yang akan terjadi pada Reinhardt? Dan musuh tak dikenal apa yang ada dalam bayang-bayang?]],
  str_mission_desc_4207015_long = "Federasi Illumina sedang melaksanakan sidang publik ketiga untuk Reinhardt atas tuduhan pengkhianatan. Saat kamu dan Vice menunggu di luar ruang interogasi, akhirnya kabar mencapai kalian bahwa Reinhardt telah dicopot dari gelar Grand Marshal dan dijatuhi hukuman penjara. Kabar ini membuat kalian berdua bertanya-tanya tentang kemungkinan adanya perubahan besar di cakrawala.",
  str_mission_desc_4207020_long = "Saat kamu merasa bingung dengan situasi saat ini, Vivian, yang bergegas datang, memanggil Vice ke samping, membicarakan tentang misi mendesak yang ada di tangannya. Kamu tiba di Stasiun Illumina dan menemukan bahwa yang menemani Vice dalam misi ini bukan hanya Charon tetapi juga tiga peserta yang mengaku berasal dari Umbraton. Mendengar hal ini, perasaan tidak nyaman mulai menyelimuti hatimu.",
  str_mission_desc_4207030_long = "Saat Anda tenggelam dalam pikiran tentang siapa yang bisa membimbing jalan ke depan Illumina, tiba-tiba siaran mengumumkan pengangkatan Wrath sebagai Grand Marshal baru. Di tengah kekagetan Anda, Leo bergegas menginformasikan kepada Anda tentang ancaman Eclipsites di Twilight. Dia memohon Anda untuk mengendarai Colossus dan menemaninya memberikan bantuan. Sementara itu, di dalam laboratorium tertentu di Illumina, sebuah rencana rahasia sedang diam-diam dilakukan.",
  str_mission_desc_4207031_long = "—",
  str_mission_desc_4207040_long = "Di bawah tatapan para penonton yang waspada, Grand Marshal yang baru diangkat, Wrath, memimpin pasukan militer baru berkumpul di stasiun, bersama mesin perang canggih, Engine VII. Meskipun Wrath kini berdiri di posisi yang telah lama ia dambakan, ia sadar bahwa ia belum mengalahkan Reinhardt secara adil dan jujur. Memikirkan hal itu, kenangan tantangan masa lalu melawan Reinhardt mulai mengalir dalam hati Wrath.",
  str_mission_desc_4207050_long = "Dengan pemahaman yang jelas tentang kekuatannya sendiri, Wrath telah lama mengantisipasi hasil seleksi akhir Grand Marshal. Meskipun akhirnya menggantikan posisi Reinhardt, ini bukan jalan yang diharapkannya. Oleh karena itu, Wrath membuat tekad dalam hati untuk sementara menjabat sebagai Grand Marshal hingga kembalinya Reinhardt, berkomitmen untuk melampaui perannya dalam setiap cara yang mungkin.",
  str_mission_desc_4207060_long = "Diberi semangat oleh motivasi dan dorongan Joselyne, para prajurit dengan gagah berani bertahan melawan serangan Eclipsites. Sementara itu, Anda dan Leo akhirnya mencapai pintu masuk Twilight. Meskipun Leo enggan untuk Anda bergabung dalam pertempuran yang genting ini, peran Anda yang menguntungkan sebagai Caelestite dan pilot Colossus meyakinkan dia sebaliknya. Pada akhirnya, bala bantuan Anda yang menghidupkan kembali semangat para prajurit di medan perang.",
  str_mission_desc_4207075_long = "Berencana untuk meminta dukungan dari Lumopolis, Zhao secara tidak sengaja menjadi tawanan anak buah Istvan. Di Pengadilan Kerajaan Lumopolis, Schwartz menggenggam beberapa permohonan bantuan, sementara para bangsawan berdebat apakah akan mengirimkan bala bantuan. Pada akhirnya, Schwartz memerintahkan pasukan pendukung untuk mempertahankan posisi mereka di Benteng Lumo, menahan diri dari keterlibatan dalam operasi militer Illumina.",
  str_mission_desc_4207080_long = "Dengan serangan Eclipsites yang semakin meningkat intensitasnya, bahkan Leo yang berpengalaman pun merasa kewalahan. Saat kelompok tersebut mempertimbangkan antara serangan berani atau mundur terus, Wrath memimpin Legiun Penjaga Illumina ke medan perang, mengubah arah pertempuran di Twilight.",
  str_mission_desc_4207090_long = "Forsakin menyadari adanya \"Seeds\" yang ditanamkan dalam prajurit-prajurit ini, yang dirancang untuk meningkatkan kemampuan bertarung mereka. Meskipun tidak puas dengan Ulysses yang mencuri temuan eksperimennya, dia menyadari bahwa Eclipsite yang tangguh yang dibawa oleh Wraith mendukung tindakan selanjutnya. Sementara itu, kamu merasakan gelombang Darkflow yang luar biasa namun masih belum menyadari bahwa mimpi buruk di Twilight baru saja dimulai.",
  str_mission_desc_4207100_long = "Setelah menyelidiki abnormalitas di antara prajurit Illumina, Leo dan Wrath memiliki diskusi panas tentang masalah dalam jajaran pasukannya. Dengan harapan mengungkap penyebab anomali prajurit, Wrath mencari bantuan Anda. Ketika Anda menyelami kesadaran prajurit yang terkorupsi dan menemukan rawa yang tak terbatas di dalamnya, di dunia nyata, Twilight juga menderita serangan tanpa henti lumpur dan Eclipsites.",
  str_mission_desc_4207110_long = "Menyaksikan nasib mengerikan prajurit yang diserang oleh Eclipsite selama eksperimen, Yingel akhirnya menyadari tujuan sebenarnya dari \"Program Phospherus\": Mereka menanamkan \"Seeds\" dalam Aurorian dan memilih prajurit luar biasa melalui pertempuran melawan Eclipsite! Tepat ketika Yingel mencoba menghentikan eksperimen, seorang subjek yang tak terkendali tiba-tiba melancarkan serangan keras terhadap mereka.",
  str_mission_desc_4207111_long = "—",
  str_mission_desc_4207120_long = "Setelah penyelidikan menyeluruh di medan perang bersama Wrath, Anda secara bertahap mengungkap mengapa prajurit Illumina rentan terhadap pengaruh lumpur. Sementara itu, lumpur terus memperluas jangkauannya ke Twilight, saat musuh yang bertindak sebagai pusat komando memanfaatkan kesempatan untuk melancarkan serangan. Dengan Wrath maju terus, Anda mengambil alih komando di medan perang tetapi secara tidak sengaja tertangkap oleh lumpur.",
  str_mission_desc_4207130_long = "Saat kamu melihat Wrath dengan sembrono menerjang ke tengah-tengah Eclipsite, kamu memutuskan untuk menggunakan Force Boost untuk masuk ke kesadarannya dan membangunkannya dari dalam. Dari ruang sidang yang tertekan hingga Kota Gannon yang basah kuyup oleh hujan, dan pemandangan Reinhardt yang terbaring di meja operasi... Akhirnya, di tengah-tengah adegan kesadaran Wrath yang selalu berubah, kamu berhasil menemukan keberadaannya.",
  str_mission_desc_4207140_long = "Anda dan Wrath akhirnya menemukan skuad terakhir pasukan Illumina. Didorong oleh kata-kata Wrath, Axelia secara bertahap mendapatkan kembali mobilitasnya. Setelah pencarian ekstensif Anda, musuh utama menampakkan diri, sementara Leo tiba, memimpin Ksatria Ekspedisi. Namun demikian, untuk melindungi timnya dari pengaruh korup lumpur, Wrath memutuskan untuk menghadapi musuh sendirian.",
  str_mission_desc_4207155_long = "Beberapa hari yang lalu, Wrath menerima pemberitahuan dari Komite—menggantikan Reinhardt sebagai Grand Marshal Illumina yang baru, dengan syarat mengikuti \"Program Phospherus.\" Dengan aspirasinya hampir tercapai, Wrath menyadari ambisinya sedang mengalami transformasi diam-diam. Pada akhirnya, dia setuju dengan syarat-syarat Komite, namun sebuah rencana juga terbentuk secara diam-diam di dalam hatinya.",
  str_mission_desc_4208015_long = "Di luar perbatasan Twilight, perubahan juga terjadi. Ketika Tim Rekayasa Illumina melacak inti \"Guardian One,\" mereka menemukan petunjuk penting yang tak terduga. Sementara itu, di dalam Istana Kerajaan Lumopolis, Hydrad, yang bertindak sebagai utusan Istvan, membahas masalah penguatan dengan Schwartz. Akhirnya, Schwartz mengambil keputusan—untuk melindungi Aurorian dengan cara Lumopolis.",
  str_mission_desc_4208020_long = "Di bawah pengaruh lumpur, beberapa prajurit Illumina berubah menjadi Eclipsites, melancarkan serangan terhadap rekan-rekan mereka sendiri. Menghadapi skenario mengerikan ini, Leo mengatur evakuasi bawahan Wrath sekaligus menangani prajurit yang berubah secara pribadi. Di tengah kekacauan, Wrath yang terluka kembali ke pertempuran, berusaha membawa kembali mereka yang terperangkap dalam kegilaan yang mengganas.",
  str_mission_desc_4208030_long = "Mengingat sumber daya medis yang terbatas di Twilight, Anda memutuskan untuk membagi menjadi tiga tim untuk operasi penyelamatan. Wrath melanjutkan pencarian prajurit Illumina yang hilang, sementara Joselyne mengawal prajurit yang terluka parah untuk mencari perlindungan di Benteng Lumo. Adapun Anda, Leo awalnya menyarankan agar Anda mengendarai Colossus dan membawa pengungsi ke tempat yang aman di Eraveil, tetapi Anda tetap pada pendirian Anda, bersikeras untuk tinggal dan menghadapi badai bersama semua orang.",
  str_mission_desc_4208040_long = "Charon tampaknya telah mengantisipasi kedatangan Victoria, namun terkejut saat mengetahui bahwa perlawanan aneh yang dihadapi bukanlah ulah Victoria. Vice, setelah mengetahui situasi di Twilight, menjadi khawatir akan keselamatanmu dan, dibantu oleh Victoria, melakukan perjalanan ke kota tersebut. Namun, setelah singgah sebentar, kekuatan aneh kembali menyerang kereta Charon.",
  str_mission_desc_4208041_long = "—",
  str_mission_desc_4208050_long = "Wahyu dari Bloody Bible membuat semua orang bingung. Victoria kemudian cepat menyadari bahwa \"Domain\" Wraith telah menyelimuti kereta. Untuk melarikan diri dari \"Domain,\" Charon melawan Wraith secara langsung, sementara Victoria dan tiga bawahannya melakukan ritual pengorbanan untuk melepaskan diri dari kesulitan. Tepat pada saat Vice berhasil menembus kepungan, kemampuan psikis Anda menangkap irama detak jantung Vice.",
  str_mission_desc_4208060_long = "Kamu berniat menyelamatkan prajurit ini dengan kemampuan psikis Anda. Namun, meskipun menyaksikan pengalaman prajurit sebelum pertempuran, kamu tetap tidak bisa menghentikan kemarahannya. Pada saat yang sama, prajurit-prajurit mulai menjadi gila satu demi satu. Ketika Leo menyarankan bahwa dia akan pergi dan menenangkan mereka, Wrath, yang berdiri sebagai Grand Marshal, memilih untuk secara pribadi memberikan akhir yang penuh belas kasihan kepada rekan-rekan yang tersiksa tak terkira.",
  str_mission_desc_4208070_long = "Saat gerbang kota terbuka lebar, sinar cahaya yang luar biasa membuat semua orang membungkuk hormat. Joselyne yang taat mengenali ini sebagai kilauan ilahi yang dibawa oleh \"Saintess\" dari Kuil Lumopolis. \"Saintess\" merawat yang terluka, mengakui usaha Joselyne, dan bertekad untuk melakukan perjalanan bersamanya ke Twilight untuk membantu mereka yang masih membutuhkan.",
  str_mission_desc_4208080_long = "Forsakin tertawa, mengatakan bahwa prajurit-prajurit yang jatuh ini adalah \"karya seni\" buatannya yang dibuat dengan teliti untuk dilihat semua orang. Kemarahan Wrath membara, namun dia tidak bertindak sembrono, waspada akan pengaruh \"Seed\" pada tubuhnya. Dalam perjalanannya untuk merebut kembali prajurit yang diambil Forsakin, Axelia menyaksikan pemandangan mengerikan prajurit yang saling menyerang. Pada saat yang paling genting, tim bala bantuan tiba.",
  str_mission_desc_4208095_long = "Vivian mengenali Anatoli sebagai sumber sinyal dan mengingat bagaimana dia menghalangi dirinya selama misi di Penjara Illumina. Ternyata Anatoli menggunakan metode ini untuk menguji tekad Vivian, dan akhirnya memutuskan untuk membantu dia menyelesaikan rencananya. Namun, ketika keduanya percaya rencana berjalan lancar, sinyal tiba-tiba terputus.",
  str_mission_desc_4208100_long = "Pertempuran di Twilight menguatkan tekad Leo untuk berdiri sebagai penjaga kota. Joselyne, yang sangat menyadari konflik antar faksi, menyatakan kepada \"Saintess\" tekadnya untuk mendirikan tempat perlindungan bagi Aurorian di dalam gereja. Namun, perang masih jauh dari berakhir. Setelah mengetahui bahwa beberapa kekuatan telah berkumpul di pertahanan Illumina, kalian semua memutuskan untuk berkumpul kembali dan maju menuju garis pertahanan.",
  str_mission_desc_4208110_long = "Di tengah pertempuran sengit para prajurit, Barton dan Hiiro tiba sebagai bala bantuan. Setelah berbagi situasi terkini, Sharona tetap cemas tentang keselamatan Wrath. Namun, kemunculan Reinhardt yang tepat waktu meningkatkan kepercayaan diri semua orang. Ternyata, rencana Wrath melibatkan tidak hanya mempertahankan Twilight tetapi juga menyelamatkan Reinhardt dan bergabung kembali dengan mereka di garis depan.",
  str_mission_desc_4208111_long = "—",
  str_mission_desc_4208120_long = "Wrath berniat memimpin pasukannya dan mengurung pasukan Eclipsite, tetapi \"Engine VII,\" yang dipengaruhi oleh Darkflow, menjadi rintangan yang tak terduga. Saat Axelia berada dalam situasi sulit melawan \"Engine VII,\" Reinhardt datang menyelamatkan. Dengan perasaan puas dan lega, Reinhardt menyaksikan Wrath kembali bergabung dengan garis depan, namun Wrath dengan senang hati mengalahkan kendali untuk memimpin pertempuran yang sedang berlangsung.",
  str_mission_desc_4208130_long = "—",
  str_mission_desc_4208140_long = "Sebelum pergi, Forsakin, mengendalikan baik tentara Illumina dan Engine VII, melancarkan serangan brutal terakhir terhadap militer Illumina. Reinhardt menyadari keterlibatan Forsakin dalam operasi Eclipse dan mencoba untuk berbicara dengannya, mendesaknya untuk patuh pada kehendaknya sendiri. Namun, respons Forsakin semakin memperbesar jurang antara saudara yang dulunya dekat. Tak lama kemudian, tentara Lumopolis dan Twilight bergabung dalam pertempuran di garis pertahanan.",
  str_mission_desc_4208155_long = "Hujan turun di garis depan Illumina. Ketika hujan berhenti, lumpur menghilang, memperlihatkan tanah di bawah sinar matahari sekali lagi. Wrath menatap korban yang banyak, menyalahkan dirinya sendiri atas kegagalannya sebagai Grand Marshal. Namun, Reinhardt memuji penampilannya, menegaskan bahwa tekadnya yang teguh telah melindungi Twilight dan para prajuritnya. Meskipun demikian, pertempuran sesungguhnya masih menanti di depan.",
  str_mission_limit_4000001 = "Navigator, bertempurlah dan selesaikan stage bersama <color=#e8d9bb>Vice</color>!",
  str_mission_limit_4000002 = "Kerahkan anggota skuad kamu dan bertempurlah bersama <color=#e8d9bb>Vice</color>!",
  str_mission_limit_4000003 = "Segera kerahkan rekan timmu untuk menyelesaikan stage bersama <color=#e8d9bb>Vice</color>. Coba sekarang juga!",
  str_mission_leader_limit_4000002 = "Navigator, <color=#e8d9bb>Vice</color> adalah kandidat Kapten terbaik!",
  str_mission_desc_4209015 = "—",
  str_mission_desc_4209020 = "Sebuah mimpi buruk yang begitu nyata membuatmu terbangun beberapa hari kemudian di saat-saat awal pagi...",
  str_mission_desc_4209030 = "Dalam kegembiraanmu, kamu berangkat tanpa mendapatkan waktu atau lokasi untuk pertemuan, dan situasi di Illumina saat ini tentu tidak terlihat baik...",
  str_mission_desc_4209040 = "Anda terkejut dengan cara Algol membuat debutnya tetapi lebih terkejut lagi dengan \"hewan peliharaan\" parasitnya.",
  str_mission_desc_4209050 = "Kamu dan Vivian terkagum-kagum ketika Algol membawamu ke kantornya. Benarkah ada tempat seperti ini di Illumina?",
  str_mission_desc_4209065 = "—",
  str_mission_desc_4209070 = "Beberapa Eclipsite tiba-tiba muncul di Taman Teknologi Illumina dan menghalangi jalanmu...",
  str_mission_desc_4209080 = "Eclipsite terus mengalir keluar dari gedung, tetapi yang lebih mengejutkan kamu adalah Ulysses diam-diam mengikuti di belakang mereka...",
  str_mission_desc_4209081 = "Tampaknya para Prajurit Illumina ini mengalami transformasi yang menakutkan di malam hari. Hati-hati!",
  str_mission_desc_4209090 = "Kata-kata Ulysses dipenuhi dengan ancaman, dan kamu telah melihat bahaya dalam visi-visinya...",
  str_mission_desc_4209100 = "Selama konferensi tinjauan kelima, Ulysses merenung tentang sebuah bab dari masa lalunya...",
  str_mission_desc_4209115 = "—",
  str_mission_desc_4209120 = "Apa hubungan prototipe yang telah lama disegel itu dengan Ulysses?",
  str_mission_desc_4209121 = "Eclipsite ini memiliki kemampuan balasan yang sangat ditingkatkan, jadi coba untuk tidak melibatkan mereka dalam pertarungan jarak dekat.",
  str_mission_desc_4209130 = "Dalam antusiasme membaca catatan Engineer, Ulysses semakin jauh dan jauh menjauh dari penelitiannya sendiri...",
  str_mission_desc_4209140 = "Melalui komputer Ulysses, Anda telah menemukan bahwa dia mengakses gudang yang tidak tercatat tanpa otorisasi...",
  str_mission_desc_4209150 = "Setelah mengalahkan pasukan super, Anda mengalihkan perhatian Anda ke prototipe yang masih berjalan...",
  str_mission_desc_4210015 = "—",
  str_mission_desc_4210020 = "Ulysses bersikeras bahwa eksperimennya memberi manfaat bagi Illumina dan berusaha membuktikan pendapatnya, tetapi hal itu sangat mengecewakan Anatoli, yang berada di dekatnya...",
  str_mission_desc_4210030 = "Untuk mempercepat dekripsi, Anda telah melakukan mind-link dengan Bool untuk menemukan petunjuk.",
  str_mission_desc_4210045 = "—",
  str_mission_desc_4210050 = "Tepat ketika Algol berpikir kamu telah mengumpulkan cukup informasi, faktor X muncul...",
  str_mission_desc_4210060 = "Apa yang akan terjadi ketika Anda masuk ke sistem Guardian?",
  str_mission_desc_4210070 = "Ketika krisis terjadi, beberapa orang panik, dan beberapa hanya tidak bisa menunggu...",
  str_mission_desc_4210071 = "Tempat di mana Prajurit Illumina sedang menjalankan misi rahasia mereka tampaknya adalah Lumopolis...",
  str_mission_desc_4210080 = "Ulysses tiba di Warehouse Zero dan dengan antusias membuka hadiah yang telah dia persiapkan selama bertahun-tahun...",
  str_mission_desc_4210090 = "Pada suara itu, kamu tiba-tiba menyadari makna dari mimpi-mimpi yang begitu nyata namun surealis...",
  str_mission_desc_4210100 = "Kau bergegas keluar tanpa berpikir, hanya untuk menemukan dirimu telah kehilangan persepsi tentang itu...",
  str_mission_desc_4210110 = "Ejekan musuh telah membuatmu marah. Bagaimana respons yang akan kamu berikan sebagai seorang Caelestite?",
  str_mission_desc_4210120 = "Insinyur telah menunjukkan tanda-tanda mundur, tetapi inti pertahanan Gannon masih hilang. Apa yang harus dilakukan sekarang?",
  str_mission_desc_4210121 = "Prajurit super yang kuat dapat meningkatkan semua musuhmu, jadi kamu harus menghentikan mereka!",
  str_mission_desc_4210130 = "Setelah inti diganti, kamu mendengar Ulysses berbicara dalam bahasa asing yang sama sekali berbeda...",
  str_mission_desc_4210140 = "Sebelum penglihatannya runtuh, dia mengingat percakapan saat perang di sanatorium...",
  str_mission_desc_4210155 = "—",
  str_mission_desc_4209015_long = "Setelah gempa bumi yang hebat, kamu dan prajurit Twilight kembali ke Eraveil setelah absen cukup lama. Para penyintas Twilight menyiapkan pesta makanan yang berlimpah; setelah kenyang menikmati hidangan sempurna, kamu memulai percakapan dengan Soroz.",
  str_mission_desc_4209020_long = "Khawatir tentang keselamatan Vice, kamu duduk di terminal Colossusmu berhari-hari, menunggu dengan cemas kabar apapun dari Reinhardt. Tiba-tiba, kamu akhirnya menerima pesan yang telah lama ditunggu-tunggu.",
  str_mission_desc_4209030_long = "Akibat masalah dengan sistem pertahanan Illumina, kamu diserang oleh Eclipsite di halaman servis Illumina. Tepat saat itu, orang yang mengundangmu ke sini muncul dengan cara yang paling tak terduga.",
  str_mission_desc_4209040_long = "Algol memperkenalkan temannya Bool, dan menjelaskan alasan mengundang Anda ke Illumina. Dia menyarankan bahwa file data Soroz mungkin berisi petunjuk mengenai Core Guardian One, yang diharapkan dapat membantu menemukan keberadaan Vice.",
  str_mission_desc_4209050_long = "Saat Anda minum secangkir kopi yang disiapkan oleh Guardian One, Vivian tampaknya akhirnya bisa sedikit rileks. Setelah istirahat sebentar, semua orang mulai bekerja. Sayangnya, tidak ada yang memberi tahu Anda tentang metode komunikasi unik dan cukup menyakitkan dari Bool...",
  str_mission_desc_4209065_long = "Setelah analisis yang panjang, Anda menemukan set koordinat yang berkedip tersembunyi dalam file data Soroz, yang tampaknya lebih tua daripada Eraveil. Algol menduga bahwa tempat kelahiran Colossi terletak jauh di dalam Dark Zone, jadi Anda mendekati salah satu fisikawan ahli Illumina untuk bertanya tentang koordinat tersebut.",
  str_mission_desc_4209070_long = "Setelah mengalahkan Eclipsite, kamu menemukan bahwa tubuh mereka memiliki kemiripan yang mencengangkan dengan Aurorian. Barton, yang sedang berpatroli di Illumina Tech Park, bergabung dengan grupmu dan semua orang menduga bahwa Eclipsite ini kemungkinan besar adalah subjek uji coba yang kabur dari laboratorium Ulysses. Dengan bantuan Alglol, kamu menuju ke laboratorium dan bersiap untuk menanyai peneliti.",
  str_mission_desc_4209080_long = "Ulysses tidak menyangkal bahwa Eclipsites sebelumnya telah melarikan diri dari laboratoriumnya, dan dia mengundang Anda lebih dalam ke gedung untuk apa yang dia sebut \"eksperimen kecil.\" Penasaran tentang sejumlah hal yang dia sebutkan, Anda menerima undangannya.",
  str_mission_desc_4209090_long = "Setelah menyaksikan adegan yang berbahaya dan mengerikan, Ulysses dibawa pergi oleh otoritas Federasi Illumina. Meski kamu masih belum yakin mengapa dia menunjukkan hal-hal ini kepada kamu, tampaknya matahari mulai bersinar lagi di Gannon City. Kamu dan teman-temanmu berharap krisis ini akan segera berakhir.",
  str_mission_desc_4209100_long = "Tahun-tahun yang lalu, seorang Ulysses yang lebih muda mengabdikan dirinya untuk meningkatkan daya hidup Aurorian. Saat meneliti teknologi rekayasa genetik Illumina, yang telah diturunkan dari berabad-abad yang lalu, dia menemukan sebuah nama yang lama dilupakan oleh sejarah. Melihat nama ini membuatnya penuh harapan untuk masa depan semua Aurorian.",
  str_mission_desc_4209115_long = "Joyce memberitahu Anda tentang batu yang mengapung, yang muncul di koordinat dalam Zona Gelap, dan informasinya cocok dengan gambar yang Anda lihat di pikiran Ulysses. Baru kemudian Algol menyadari bahwa Ulysses telah menyembunyikan pekerjaannya pada prototipe Guardian sepanjang waktu.",
  str_mission_desc_4209120_long = "Dalam sidang, semua orang terkejut mengetahui bahwa Ulysses telah diam-diam melakukan penelitian tentang mesin kuno. Seiring terungkapnya fakta ini, Anda dan Algol terus mencari prototipe di Gannon City. Namun, yang sama berbahayanya dengan mesin ini adalah super-prajurit yang memancarkan Darkflow dan bersembunyi di bayangan.",
  str_mission_desc_4209130_long = "Ulysses mengusulkan eksperimen yang berani, yang membuat Robby, rekan kerjanya sejak lama, meragukannya. Siapa \"the Engineer,\" dan bagaimana dia meyakinkan Ulysses untuk mengambil tindakan radikal dengan penelitiannya?",
  str_mission_desc_4209140_long = "Ketika Algol tiba di Gudang Nol, dia sangat senang mengetahui bahwa prototipe Guardian masih beroperasi. Sayangnya, penyusupanmu juga memicu serangan oleh super-prajurit yang disimpan di gedung tersebut.",
  str_mission_desc_4209150_long = "Ketika Algol pertama kali melihat prototipe tersebut, dia masih merupakan seorang siswa dari Ulysses. Yang lebih mengejutkan, bagaimanapun, adalah fakta bahwa Ulysses tetap menjaga agar tetap beroperasi di gudang pribadinya bahkan setelah disegel untuk alasan keamanan. Saat kamu dan teman-temanmu mencoba mengakses prototipe misterius tersebut, kamu dipenuhi dengan campuran antisipasi dan ketakutan.",
  str_mission_desc_4210015_long = "Anda terkesima oleh fungsi dan kecepatan pemrosesan Bool yang mengesankan. Saat Algol menceritakan kisah pertama kali mereka bertemu, Anda perlahan menyadari makna di balik label di tubuhnya.",
  str_mission_desc_4210020_long = "Terungkap bahwa tujuan sebenarnya dari Undercity 80 adalah untuk memilih kandidat untuk proyek Artificial Sun. Sementara mengumpulkan informasi penting tentang proyek tersebut, tim pengintaian Anatoli pada akhirnya dihancurkan. Tidak mau menerima kehilangan timnya, Anatoli menuntut agar Committee mencoba dan menghukum Ulysses atas kejahatannya.",
  str_mission_desc_4210030_long = "Setelah menggunakan kekuatan psikis Anda pada Bool, Anda kewalahan oleh gelombang tak berujung dari angka dan urutan. Untuk mengekstrak informasi yang Anda butuhkan, Algol berbagi triknya dalam menangani beban kerja yang sulit dengan Anda. Anda mencoba lagi, dan tampaknya berhasil mendapatkan beberapa data yang berguna.",
  str_mission_desc_4210045_long = "Sama seperti Yingel dan Axelia, Sean juga merupakan produk dari Program Phospherus. Namun, Sean dianggap gagal di awal program, dan dikirim ke Twilight. Setelah mengetahui asal-usulnya, Sean mulai bertanya-tanya apakah tujuan hidupnya adalah menjadi senjata perang yang tak kenal belas kasihan.",
  str_mission_desc_4210050_long = "Menghubungkan dengan pikiran Bool menyebabkan Anda merasa pusing dan tidak nyaman. Algol memberi Anda batas waktu dua menit, selama waktu itu Anda diinstruksikan untuk mengambil sebanyak mungkin informasi. Untungnya, Anda keluar dengan relatif selamat, tetapi sesuatu tampaknya mengganggu Algol. Apa yang bisa meruntuhkan peradaban yang cukup maju untuk menciptakan teknologi ini?",
  str_mission_desc_4210060_long = "Anda terkejut dengan situasi di Kota Gannon. Algol terus mencari cara untuk masuk ke dalam sistem, hanya untuk mengetahui bahwa gempa bumi yang hebat disebabkan oleh musuh yang tidak terlihat. Percobaan Ulysses juga ditangguhkan sementara. Tepat ketika Anda berpikir krisis hampir berakhir, musuh yang tidak terlihat muncul di layar prototipe...",
  str_mission_desc_4210070_long = "Ulysses mengklaim telah merancang cara untuk mengalahkan musuh, dan Belisaria setuju dengan operasinya, mengubah persiapan sebelumnya, dan segera meluncurkan rencana yang telah dibuat sebelumnya.",
  str_mission_desc_4210080_long = "Para super-prajurit yang disimpan di gudang adalah hasil dari penelitian ilmiah Ulysses selama bertahun-tahun, serta hadiahnya untuk Engineer. Namun, sangat mengejutkan Ulysses, Engineer segera mengambil alih mereka dan menggunakannya untuk menyerang semua rekan sejawat Illumina.",
  str_mission_desc_4210090_long = "\"Pulanglah, Caelestite.\" Sebuah pesan misterius bagi banyak orang, tetapi satu yang telah Anda dengar dalam mimpi Anda berkali-kali. Siapa dia? Ke mana tepatnya dia ingin Anda pergi? Saat Anda berjuang sekuat tenaga, Anda tiba-tiba menerima kabar bahwa Soroz telah diaktifkan.",
  str_mission_desc_4210100_long = "Saat perpisahan akhirnya tiba, namun kamu tidak merasakan apa-apa. Untuk alasan yang tidak diketahui, kamu telah memainkan skenario ini dalam pikiranmu lebih banyak dari yang bisa kamu hitung. Bahaya mengikuti dekat di belakang kesedihanmu, tetapi seorang teman kecil melangkah dan memblokir pukulan fatal yang ditujukan untukmu.",
  str_mission_desc_4210110_long = "Dalam kesadaran Figerald, tampaknya kamu menyaksikan proses di mana Engineer memperbudak orang lain. Tidak hanya itu, kamu melihat kenangan jauh tentang jurang yang menganga dan sisa-sisa kerangka Colossi yang muncul dari dalam pikiran Figerald...",
  str_mission_desc_4210120_long = "Untuk melindungi Kota Gannon, pendamping Algol, Guardian One, dengan tegas menawarkan Core miliknya sendiri. Sementara itu, untuk mendapatkan cukup daya komputasi untuk transisi, Reinhardt menjalankan protokol darurat untuk mengarahkan daya pemrosesan setiap komputer di Kota Gannon ke lokasi mereka.",
  str_mission_desc_4210130_long = "Algol menemukan bahwa bahasa komputer yang digunakan oleh Sistem Guardian somehow terkait dengan bahasa yang digunakan oleh Eclipsite. Ulysses berbangga bahwa dia bisa mengubah seluruh dunia, tetapi kamu tidak memiliki keinginan untuk hidup di dunia yang dimodifikasi oleh tangannya.",
  str_mission_desc_4210140_long = "Mana yang lebih tragis, kehilangan keyakinan atau ketidakmampuan untuk mewujudkan impian? Ulysses bertanya padamu satu pertanyaan terakhir sebelum jatuh di kakimu. Tidak lagi mampu menjawab, ini mungkin kali terakhir dia merenungkan pertanyaan ini.",
  str_mission_desc_4210155_long = "Setelah tidak sadarkan diri selama tiga hari, kamu bangun dan menemukan bahwa krisis di Gannon City sudah berlalu. Namun, yang menunggumu sekarang adalah misi eksplorasi yang lebih berbahaya. Kamu mengingat bagaimana kamu diselamatkan saat menggunakan kekuatanmu, dan bertanya-tanya apakah ada orang di ruang yang berkilau seperti danau itu yang bisa memberimu petunjuk yang kamu cari.",
  str_mission_desc_4301015 = "—",
  str_mission_desc_4301020 = "Dalam pusat komando sementara yang luas, Komite Ekspedisi Astra Bersama mengadakan konferensi penting mengenai masa depan Aurorian.",
  str_mission_desc_4301030 = "Karena menghadapi arus udara ekstrem, pesawatmu jatuh secara tak terduga di dataran salju di tepi Northland...",
  str_mission_desc_4301040 = "Kamu mengikuti jejak darah, namun secara misterius jejak itu menghilang di tengah jalan...",
  str_mission_desc_4301055 = "Saat Bethlehem mengantar kamu keluar dari gua, dia merasakan medan energi unik di dalamnya dan merumuskan solusi untuk mengatasi kesulitan tersebut.",
  str_mission_desc_4301060 = "Menghadapi krisis saat ini di Northland, Bethlehem mencari nasihat dari Tetua Fox Salju tentang membangkitkan Primal Haven untuk membersihkan polusi yang menjangkiti dataran salju.",
  str_mission_desc_4301070 = "—",
  str_mission_desc_4301080 = "Saat salju tebal menutupi perbatasan, kamu mencapai suku yang membesarkan Tiare, mulai mencari pohon cemara ketiga.",
  str_mission_desc_4301090 = "Dengan terbangunnya Primal Haven, mercusuar baru didirikan. Tiare mengacungkan tombaknya yang kuat, sekali lagi menuju Eclipsite yang perkasa itu.",
  str_mission_desc_4301105 = "—",
  str_mission_desc_4301015_long = "Bethlehem mengenang pertemuan di masa lalu. Bertahun-tahun yang lalu, saat berpatroli di Hutan Snowpine di tepi Northland, dia sempat bertemu dengan Snow Fox yang tinggal di sana. Tiare, anak yang dibesarkan oleh Snow Fox itu, kini menjadi pengawal Bethlehem, tinggal di Istana Musim Dingin, namun masih khawatir tentang sukunya.",
  str_mission_desc_4301020_long = "Delegasi dari Lumopolis, Umbraton, dan Courier Union telah bertukar pendapat tentang persiapan eksplorasi Federasi Illumina. Setelah pertemuan, Reinhardt menugaskan kamu dan Carleen untuk menyelidiki status pendirian pos luar Northland.",
  str_mission_desc_4301030_long = "Secara tidak sengaja tersandung ke wilayah suku perbatasan, kamu bingung dengan noda-noda darah yang tersebar di tanah. Reaksi berikutnya dari Tiare dan Rubah Salju menunjukkan bahwa masalahnya tidak sesederhana yang tampak. Meskipun mereka sangat menentang, kamu masih memutuskan untuk mengikuti mereka untuk melihat apa yang sebenarnya terjadi.",
  str_mission_desc_4301040_long = "Mengatasi rasa takut dalam dirimu, kamu menggunakan Kemampuan Psikis untuk melacak Tiare dan rubah salju. Akhirnya, kamu menemukan bekas darah yang mereka tinggalkan dan secara tak terduga mengetahui bahwa dua teman Rediesel Wrenchmu juga telah datang ke Northland dengan pesawatmu. Namun, sedikit yang kamu ketahui, seorang Eclipsite yang kuat sedang mengintai di dekatnya.",
  str_mission_desc_4301055_long = "Dipimpin oleh Sesepuh Fox Salju, kamu tiba di altar kuno yang dijaga oleh suku Fox Salju selama berabad-abad. Di sini, kekuatanmu beresonansi dengan kekuatan kuno, dan legenda \"Tiga Pohon Pinus\" terungkap. Menjadi kejutan bagi Sesepuh Fox Salju, bukan keluarga kerajaan yang mengambil pinus, tetapi pinuslah yang memilih keluarga kerajaan dan mengakui ratu.",
  str_mission_desc_4301060_long = "Saat Bethlehem menghadapi Eclipsite sendirian, kamu memutuskan untuk mencari dua pohon pinus lainnya bersama Tiare. Novio menyarankan bahwa karena kekuatan kuno telah memudar, untuk menemukan pohon pinus, kamu harus mencari petunjuk dari legenda \"Tiga Pohon Pinus.\"",
  str_mission_desc_4301070_long = "Membawamu di pundaknya, Tiare berlari sepanjang jalan, akhirnya sampai di Pengadilan Northland. Ketika kamu bingung, kata-kata Zarya memberikan petunjuk. Ternyata pohon pinus yang ditebang telah lama diukir menjadi takhta ratu, tetapi karena ratu tidak pernah duduk di atasnya, takhta itu telah mengumpulkan debu di pengadilan.",
  str_mission_desc_4301080_long = "Menyelami kenangan Tiare, kamu menemukan perselisihan antara Penatua Salju Fox dan nenek Tiare mengenai masa depannya. Isu utama perselisihan mereka adalah sesuatu tentang sebuah lempengan batu yang melambangkan komitmen kuno, yang tepatnya adalah apa yang kamu cari. Dengan bantuan Tiny One dan Roy, kamu berhasil menemukan pohon cemara ketiga dan membawanya kembali ke altar.",
  str_mission_desc_4301090_long = "Serangan Tiare membangkitkan kenangan di dalam Eclipsite, mengingatkannya akan masa lalunya dan alasan di balik latihan kerasnya. Saat dia mencoba melakukan serangan terakhir terhadapmu, kamu mengusirnya keluar dari Northland. Di bawah cahaya Beacon, kamu mengambil langkah bersejarah maju, berani memasuki Dark Zone.",
  str_mission_desc_4301105_long = "Meskipun Eclipsite masih belum terkalahkan dan pos luar Northland masih dalam tahap pembangunan, kamu bertekad untuk melakukan persiapan aktif dan melanjutkan penjelajahanmu ke Dark Zone di waktu yang akan datang. Sebelum berangkat, kamu menerima Lumina Ore yang dikirim oleh Tiare. Berdiri di dekatnya, Bethlehem merasa tenang dan puas, mengetahui bahwa penjaga Northland, Tiare, telah tumbuh dan dewasa.",
